window.READER_DATA={"title": "Yakan Islam Jins", "slug": "yakan-islam-jins", "pages": [{"n": 1, "paras": ["فتحي يكن", "الإسلام والجنس", "مؤسسة الرسالة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0001.png"}, {"n": 2, "paras": ["حقوق الطبع محفوظة الطبعة الثانية", "١٣٩٥ ه - ١٩٧٥ م", "مؤسسة الرسالة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0002.png"}, {"n": 3, "paras": ["بسم الله الرحمن الرحيم", "مقدمة", "إن استفحال المشكلة الجنسية في العالم وتسببها بتفتيت الأسس والكيانات المجتمعية، ونسف الأطر الأخلاقية والمسلكية يوجب طرحها كنتيجة للحضارة المادية ، ودليل على فشل هذه الحضارة وافلاسها في ايجاد المجتمع الانساني الكريم . كما ان ذلك يسوق كذلك إلى طرح البديل المنقذ .. لأنه ان كان من المهم هدم الواقع الفاسد فان من الأهم بناء الواقع السليم الحسن .. إن المشاكل التي تعيشها البشرية لا تواجه بمجرد تحديد مواصفاتها ، وانما بتقديم الحلول الجذرية لها . إن الغريزة الجنسية بحاجة إلى نظام فطري يتولى تقييمها وتوجيهها .. نظام يحقق البعد الانساني منها صيانة الفرد والمجتمع من أخطارها وأضرارها ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0003.png"}, {"n": 4, "paras": ["إن الحلول - كل الحلول - المطروحة بشأن المشكلة الجنسية لا تؤمن التوازن المطلوب بين تحقيق اللذة وعدم الاضرار ، وبين ممارسة الجنس وصيانة الأخلاق . وهذا الكتاب يبحث في المنهج الذي يحقق هذا التوازن الفطري العجيب .. سائلا الله تعالى أن يحقق النفع به ويجزل الأجر . وإن الله لهادي الذين آمنوا إلى صراط مستقيم ) .. المؤلف", "٥ / ذي الحجة / ١٣٩٢", "٢١ / كانون الثاني / ١٩٧٢"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0004.png"}, {"n": 5, "paras": ["التصور عنوان التصرف", "الانسان يصدر في كل تصرفاته وأفعاله عن التصورات التي يحملها وعن العقيدة التي يعتنقها . ويصعب أن تجد انساناً ليس له تصور معين عن الكون والانسان والحياة ..", "فالانسان الذي يؤمن بالبديهيات الكونية . يعرف كيف خُلق ولم .. وانه سيموت ، ثم يبعث يوم القيامة ليجزى خيراً بخير وشر أ يشر ، لا بد وأن تنسجم تصرفاته في الحياة وفق تصوره ذاك ..", "والملحد الذي يُنكر وجود الله ، ويكفر بالبعث ، ويعتبر أن الحياة مادة ، سيتوافق تصرفه حتماً مع هذا التصور ومع النظام والسلوك الدين انبثقا عنه ..", "حتى الضائع بين هذا وذاك، يكون تصرفه في الحياة متوافقاً مع ضياعه وشروده .. فتارة إلى هؤلاء وتارة إلى اولئك دون أن يلتزم نهجاً واحداً ..", "ه"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0005.png"}, {"n": 6, "paras": ["تصحيح التصور هو الأساس", "لذلك كان كل تصحيح أو تغيير في واقع الحياة البشرية لا يعتمد على فكر ضرباً من العبث .. فالانسان يُقاد بفكره أولاً وان كان لا ينكر أثر غرائزه عليه كذلك . بل ان هذه الغرائز بالذات يكون اشباعها وتصريفها متوافقاً مع الفكر الذي يحمله الانسان ..", "إن سلوك الانسان في الحياة هو في الحقيقة انعكاس لمفاهيمه وأفكاره وليس العكس كما تزعم الفلسفة المادية التي تعتبر الفكرة وليدة المادة والسلوك وان المادة هي صانعتها .", "يقول انجليز : ( ان العالم المادي الذي تدركه حواسنا، والذي ننتمي نحن أنفسنا اليه ، هو الواقع الوحيد ، إن ادراكنا وفكرنا مهما ظهرا رفيعين ساميين ، ليسا سوى نتاج عضو مادي جسدي هو الدماغ .. ان المادة ليست من نتاج العقل ، بل ان العقل نفسه ليس سوى نتاج المادة الأعلى ) .", "لذلك كان اعتماد الاسلام الأول في عملية تحويل المجتمع من مجتمع جاهلي إلى مجتمع اسلامي يقوم على احلال مفاهيمه العقيدية عن الكون والانسان والحياة .. وعلى اذكاء جذوة التفكير والنظر لدى الانسان ، حتى يتمكن بهما من فهم هذه العقيدة واعتناقها بعمق واصالة .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0006.png"}, {"n": 7, "paras": ["يقول الله تعالى في القرآن الكريم ( فلينظر الإنسان مم خلق .. خلق من ماء دافق يخرج من بين الصلب والترائب ) ( ان في خلق السموات والأرض واختلاف الليل والنهار والفلك التي تجري في البحر بما ينفع الناس ، وما أنزل الله من السماء من ماء فأحيا به الأرض بعد موتها ، وبث فيها من كل دابة ، وتصريف الرياح والسحاب المسخر بين السماء والأرض لآيات لقوم يعقلون )", "هذه وغيرها من الآيات التي يحفل بها القرآن الكريم تبين اسلوب المنهج الاسلامي في صياغة الأفراد والجماعات وفي بناء وتكوين الشعوب والمجتمعات .", "انه الاسلوب الذي يبدأ بصياغة الفكر وينتهي إلى صياغة الواقع في كل شؤونه وأحواله ..", "وعبثاً تحاول الاتجاهات المادية والنظم الوضعية تصحيح الواقع الانساني من خلال الاصلاحات المادية المعيشية فحسب .. وصدق الله تعالى حيث يقول : ( ان الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم )"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0007.png"}, {"n": 8, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0008.png"}, {"n": 9, "paras": ["الثورة الجنسية أسبابها ونتائجها", "لم يعد الكلام عن الجنس محصوراً اليوم في نطاق النظريات (التجريدية)، أو في حدود التصورات التقليدية (الكلاسيكية) لهذا الموضوع .. فالعالم الذي يعيش اليوم ثورة جنسية طاغية ، تجاوزت كل الحدود والقيود ، لعل القضية تطرح على انها أبرز احدى القضايا وأشدها أثراً وخطراً على الكيان البشري برمته ..", "يقول « جورج بالوشي هورفت » في كتابه «الثورة الجنسية»", "( والآن ، وبعد أن كادت أذهاننا تكف عن الخوف من الخطر الذري، ووجود (سترونيتوم ٩٠) في عظامنا وعظام أطفالنا. لا يفتقر العالم إلى عناصر بشرية تقلق للأهمية المتزايدة التي يكتسبها الجنس في حياتنا اليومية ، وتشعر بالخطر إذ ترى موجة العري وغارات الجنس لا تنقطع . ينشغل هؤلاء الناس انشغالاً جاداً بالقوة الهائلة التي يمكن أن"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0009.png"}, {"n": 10, "paras": ["تصل اليها الحاجة الجنسية إذا لم يحدها الخوف من الجحيم ، والأمراض السارية ، والحمل .. وفي رأيهم ان أطناناً من القنابل الجنسية تنفجر كل يوم ، ويترتب عليها آثار تدعو إلى القلق ، قد لا يجعل أطفالنا وحوشاً أخلاقية فحسب ، بل قد تشوه مجتمعات بأسرها )", "وكتب جيمس رستون في النيويورك تايمز مؤخراً ( إن خطر الطاقة الجنسية قد يكون في نهاية الأمر أكبر من خطر الطاقة الذرية ؟؟ )", "ويلفت المؤرخ ارنولد توينبي النظر إلى ان سيطرة الجنس يمكن أن تؤدي إلى تدهور الحضارات .. وهذا ما أكده الاسلام من قبل حيث يقول الرسول صلى الله عليه وسلم : ( وما تشيع الفاحشة في قوم قط إلا عمهم الله بالبلاء )", "إن اميركا واوروبا وغيرهما من بلاد العالم تشهد منذ سنوات قريبة جنوناً جنسياً محموماً ، سواء في عالم الأزياء والتجميل ، أو في عالم الكتب والأفلام ، أو في عالم الواقع على كل صعيد .. حق غدا الجنس الشغل الشاغل لمعظم أفراد المجموعة البشرية ، بل أضحت ممارسته والاغراق فيه غاية الحياة وقمة الامنيات لدى كثير من الناس .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0010.png"}, {"n": 11, "paras": ["فلم يعد الجنس تلك العلاقة الحسية القائمة بين زوجين اثنين أو حق بين شخصين لا يربطهما عقد شرعي أو قانوني ، بل أضحى عالماً واسعاً بكل ما فيه من فنون ووسائل ومثيرات ؟؟ غدا الجنس كالطعام مختلفة ألوانه متعددة توابله ومقبلاته ، لا يخضع لذوق أو مزاج أو قاعدة ، فضلاً عن تحرره من كل عرف أو تقليد ؟؟", "في الواقع يستحيل اليوم السير في أي مدينة كبيرة دون التعرض ( للقصف الجنسي ) الحقيقي .. اعلانات من كل حجم ، مجلات وأغلفة مصورة ، أفلام سينمائية ، صور معروضة في مداخل علب الليل ، وآلاف من الفتيات والنساء يرتدين ثياباً كان يمكن أن توصف بقلة الحشمة منذ أمد قريب ؟ .", "إن اللواط والسحاق والممارسات الجماعية للجنس والزواج التجريبي أو الحب السابق للزواج ، وان نوادي الشذوذ والفارسونيرا والستيريهات ونوادي العراة وعلب الليل ، وان المجلات الماجنة والأفلام الجنسية والصور الخليعة الخ . كل هذه وغيرها باتت السمة المميزة للمجتمعات البشرية في شتى أنحاء الأرض ..", "هذه الثورة الجنسية المحمومة التي بدأت طلائعها منذ سنوات كانت حصاد أوضاع وقيم عقائدية وفكرية وأخلاقية معينة . لم تكن هذه الظاهرة وليدة الصدفة أبداً . وانما كانت نتيجة واقع ، وثمر شجرة نمت وتغذت من هذا الواقع .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0011.png"}, {"n": 12, "paras": ["كان حصول كل ذلك متوقعاً ومنتظراً منذ اللحظة الأولى التي بدأ الفكر المادي يجتاح الوجود الانساني.. منذ اللحظة التي انقطعت فيها الصلة بين الكائن البشري وبين الحقائق والمسلمات الغيبية . منذ اللحظة التي أنكر الناس فيها وجود الله، وبالتالي وجود ضوابط أخلاقية لحياتهم ، وعقوبات ربانية لتصرفاتهم ؟؟ منذ تلك اللحظة غدا الانسان حيواناً يعيش بغرائزه ولها ، ويحيا لنزواته وبها .. تعطلت فيه نوازع الخير، واستيقظت لديه نوازع الشر .. أصبح والشهوات أكبر همه والدنيا مبلغ علمه ( اولئك كالأنعام بل أضل سبيلا ) .", "إن غيبة الفكر الديني عن دنيا الناس ، وتعطل حاكمية الله في الأرض ، وهيمنة التشريعات والنظم والقوانين المنبثقة عن النظريات المادية كانت العامل الأساسي في انحراف سير القافلة البشرية عن الطريق القويم ، وانطلاقها في متاهات الضياع والشرود .", "ان المسؤولية الأولى انما تقع على هذه الاتجاهات والفلسفات المادية التي تقدم للانسانية قاطبة مبرارات وذرائع الانحراف والشذوذ ؟", "جاء في البيان الشيوعي ( ليس الشيوعيون بحاجة إلى ادخال اشاعة النساء ، فهي تقريباً كانت دائماً موجودة . ولا يكتفي البورجوازيون بأن يكون تحت تصرفهم"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0012.png"}, {"n": 13, "paras": ["نساء العمال وبناتهم . بل يجدون لذة خاصة في اغواء بعضهم لنساء بعض . ليس الزواج البورجوازي في الحقيقة والواقع سوى اشاعة النساء المتزوجات . فقصارى ما يمكن ان يتهم به الشيوعيون اذن ، هو انهم يريدون ابدال اشاعة النساء المستترة بالرياء المغطاة بالمداجاة باشاعة صريحة رسمية ) صفحة ٥٢", "إن الانسان المكون من النوازع المادية والروحية والمتطلبات البدنية والنفسية لا يمكن ان ينعم بالراحة والاطمئنان ما لم يحقق اشباع احتياجاته الفطرية كلها .. وانسان القرن العشرين إذ يلهث وراء اشباعاته العضوية الغريزية دون ان يتمكن من تحقيق هذه الاشباعات .. وهو إذ يسرف في ذلك ويبالغ طلباً للراحة والسعادة من غير ان تتحقق له . فلكونه أهمل الجزء الأساسي من تكوينه ، والاحتياج الأهم في تركيبه . أهمل نفسه وروحه ..", "إن الاتجاهات المادية فشلت فشلاً ذريعاً في تحقيق الطمأنينة والاستقرار للانسان .. وان المدنية الحديثة على كثرة منجزاتها العلمية والتقنية لم تتمكن من سد الفراغ والجوع النفسيين في حياة الكائن البشري .. بل ان هذه الاتجاهات المادية تسببت في كثير من حالات التوتر والانهيار العصبيين وفي انتشار وتكاثر الأمراض النفسية مما تشهد وقائعه بالأرقام مصحات الأمراض العصبية في شتى انحاء العالم .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0013.png"}, {"n": 14, "paras": ["كانت ( مارلين مونرو ) من أجمل نساء القرن العشرين . والمستوى الذي وصلته كرمز للجنس لم تصل اليه امرأة اخرى وذات يوم من صيف ١٩٦٢ ولسبب ما ، أدركت ان هذا الرمز سيتداعى ، وان هذا الجمال سيذبل ويزوي ، وان هذه الشهوة ستضمحل وتموت، فابتلعت كمية من الحبوب المنومة وضعت بها نهاية لحياتها التعيسة القلقة ؟؟", "وكما وقع لمارلين مونرو وقع لجين هارلو ولزوجة المركيز الايطالي بل لمئات الآلاف من ضحايا الجنس يقضون قتلاً أو انتحاراً هنا وهناك ؟؟", "في نيسان سنة ١٩٦٤ اثيرت في السويد ضجة كبرى عندما وجه ١٤٠ من الأطباء المرموقين مذكرة إلى الملك والبرلمان يطلبون فيها اتخاذ اجراءات عاجلة للحد من الفوضى الجنسية التي تهدد حقاً حيوية الأمة وصحتها . طالب الأطباء بقوانين ضد الانحلال الجنسي ؟؟", "وفي أيار سنة ١٩٦٤ قامت أكثر من ألفي انجليزية بحملة ( تنظيف موجات الاذاعة وشاشات التلفزيون من الوحل الذي يلطخها ) وفي أول اجتماع لهن قال أحد المذيعين ( يوجد في الخارج اناس يتمنون أن تهدم الأخلاق الجديدة العصب الاخلاقي في بلدنا ) .", "حق في الصين الشعبية يشعر اتباع ( ماوتسي تونغ ) انهم مضطرون للقيام بحملة واسعة النطاق ضد الحب الحسي اللاجتماعي."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0014.png"}, {"n": 15, "paras": ["ويرى كل من الاتحاد السوفياتي وبولندا والمانيا الغربية انهم مضطرون لالقاء نظرة جديدة على قضايا الحب والأخلاق الفردية .. وفي سنة ١٩٦٢ صرح كنيدي بأن مستقبل اميركا في خطر لأن شبابها مائع غارق في الشهوات لا يقدر المسئولية الملقاة على عاتقه . وانه من بين كل سبعة شبان يتقدمون للتجنيد يوجد ستة غير صالحين .. لأن الشهوات التي غرقوا فيها افسدت لياقتهم الطبية والنفسية ؟؟ (١) ان هذه الصيحات التي بدأت تستنكر مؤخراً الانحرافات الجنسية الخطيرة التي آلت اليها المجتمعات العالمية قاطبة ، لم تصل بأصحابها ومطلقيها إلى النقطة التي يمكن منها الانطلاق إلى التصحيح والتقويم .. لأنها لم تكن إلا بمثابة ردة فعل عابرة غير مرتكزة على أسس عقيدية وأخلاقية سليمة .. إن تصحيح الواقع الاجتماعي والأخلاقي لا يتحقق بمجرد استهجان القبيح واستنكاره ، وانما بتقويم المجتمع وبنائه في كافة مرافقه وشؤونه وفق نظام أخلاقي متناسق .. وإذا كانت الأخلاق والقيم والمثل الكريمة لا يمكن صدورها عن غير أصول عقيدية .. فتصبح بالتالي استقامة موازين الأخلاق في العالم ضرباً من المحال ، ما دامت الأفكار القائمة والنظم الحاكمة أفكاراً ونظماً مادية لا أخلاقية بل ومتعارضة تمام المعارضة مع الفكر والسلوك الدينيين ؟؟", "(١) راجع كتاب الثورة الجنسية لجورج بوشي هورفات ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0015.png"}, {"n": 16, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0016.png"}, {"n": 17, "paras": ["الأخلاق والجنس", "للأخلاق في نظر الماديين مفاهيم غريبة لا تتفق في شيء مع ما تعارف عليه الناس ومع ما جاءت به الأديان ، بل حتى مع الحس والذوق الفطريين .. ونحن هنا لا نود أن نتكلم عن الأخلاق من الجانب التقليدي المعروف ، وانما من جانب ارتباطها وعلاقتها بالجنس ( موضوع هذا الكتاب ) .. إن المذاهب المادية جمعاء تعتبر الجنس عملية ( بيولوجية ) بحتة لا علاقة لها بالأخلاق ، كما تعتبر ان السياسة هي سياسة كذلك ولا علاقة لها بالأخلاق .. يقول دركايم : ( ان الأخلاقيين يتخذون واجبات المرء نحو نفسه أساساً للأخلاق . وكذا الأمر فيما يتعلق بالدين ، فان الناس يرون انه وليد الخواطر التي", "الاسلام - ٢"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0017.png"}, {"n": 18, "paras": ["تثيرها القوى الطبيعية الكبرى أو بعض الشخصيات الفذة ( يعني الرسل ) لدى الانسان . ولكن ليس من الممكن تطبيق هذه الطريقة على الظواهر الاجتماعية اللهم إلا إذا أردنا تشويه الطبيعة )١( .", "ويقول فرويد : ( ان الإنسان لا يحقق ذاته بغير الاشباع الجنسي .. وكل قيد من دين أو أخلاق أو مجتمع أو تقاليد هو قيد باطل ومدمر لطاقة الانسان وهو كبت غير مشروع ) .", "ومن يوم استبدلت أوروبا بالدين الفلسفة ، وفصلت الدين عن الحياة ، وجعلت ما لقيصر لقيصر وما لله لله ، بدأ الانحراف في المفهوم الأخلاقي لدى الشعوب . انه تبعاً لفقدان القواعد الدينية على الأخلاق غدا مفهومها عرضة للتفسيرات والتقويمات البشرية الشتى .. كل ذلك أدى وبصورة تدريجية وتلقائية إلى أن يصبح للأخلاق قيماً مادية نفعية أخذت تعريها على الزمن من مدلولاتها الفطرية الأصلية .. وهذه نتيجة حتمية لانفصالها - أي الأخلاق - عن ( الدين ) المدد الطبيعي الذي يجدد حيويتها ويمنحها المعطيات الخيرة والآثار الحميدة ..", "(١) قواعد المنهج في علم الاجتماع ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0018.png"}, {"n": 19, "paras": ["يقول الأستاذ محمد قطب : ( ان الأخلاق ليست شيئاً منفصلاً عن الواقع . ليست نظريات تدرس في الأبراج العاجية مستقلة بذاتها . وليس لها قوانين خاصة غير قوانين الحياة الواقعية ؟ ولا يمكن أن يوجد فساد ( خلقي ) مع استقامة في حياة الناس الواقعية .. انما شيء واحد .. والفساد في واقع الحياة معناه فساد في الأخلاق ... الفساد في الأخلاق معناه فساد في واقع الحياة .. لأنها قانون مستمد من الوجود البشري المتكامل والفطرة البشرية الشاملة ) (١) .", "إن النتيجة الحتمية لانطلاق الغرائز ولاباحة الجنس إباحة مطلقة هي تهدم الأخلاق وانعدام الفضائل وانهيار الشعوب والأمم .. وهذا ما تؤكده الحركة الصهيونية التي تعمل على تقويض الشعوب - كل الشعوب غير اليهودية - بالجنس . جاء في بروتوكولات حكماء صهيون : ( يجب أن نعمل لتنهار الأخلاق في كل مكان فتسهل سيطرتنا .. إن فرويد منا وسيظل يعرض العلاقات الجنسية في ضوء الشمس لكي لا يبقى في نظر الشباب شيء مقدس ، ويصبح همه الأكبر هو ارواء غرائزه الجنسية وعندئذ تنهار أخلاقه ) .", "(١) جاهلية القرن العشرين"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0019.png"}, {"n": 20, "paras": ["وجاء فيها أيضاً : ( لقد رتبنا نجاح دارون وماركس ونيتشه بالترويج لآرائهم . وان الأثر الهدام للأخلاق الذي تنشئه علومهم في الفكر غير اليهودي واضح لنا بكل تأكيد ) .", "إن هذا المفهوم من شأنه أن يكشف كثيراً من الأسرار والملابسات الكامنة وراء الهزائم المتلاحقة التي منيت بها أمتنا وبخاصة هزيمة عام ١٩٦٧ حيث لعب « الجنس » الدور الأساسي في حبك المؤامرة وفي انزال الضربة القاضية بسلاح الجو المصري وصدق الشاعر حيث يقول : فانما الأمم الأخلاق ما بقيت فان هموا ذهبت أخلاقهم ذهبوا"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0020.png"}, {"n": 21, "paras": ["فلسفة الأخلاق في الإسلام", "الفلسفة الأخلاقية في الإسلام تقوم على أساس توفيق تصريف الغرائز كل الغرائز وتنظيم العلائق والتصرفات كل العلائق والتصرفات البشرية وفق تصور الاسلام العقيدي ووفق النظام المنبثق عن هذا التصور ..", "انه الإطار الذي يعمل على تقعيد جميع شؤون الحياة الاجتماعية منها والاقتصادية والسياسية ، الفردية منها والجماعية وفق اسس أخلاقية ليكون التعامل بها ، وليكون الأثر الناتج عنها أخلاقياً ..", "ان الأخلاق في المنهج الاسلامي ليست نظاماً خاصاً أو مجموعة تعاليم ومثل منفصلة عن جسم هذا المنهج واجزائه . انما هي معطيات خيرة وروح كريمة تنسياب انسياباً متوافقاً منسجماً في كل جانب من جوانب المنهج الاسلامي بل في كل جزئية من جزئياته .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0021.png"}, {"n": 22, "paras": ["فاذا كان النظام السياسي في الاسلام يقوم على مبادىء أخلاقية فمن أولى أن يتم تصريف الغرائز وفق هذه المبادىء تحقيقاً للأخلاقية في أعمال الانسان كلها ، الفكرية منها والفنية ، الاقتصادية منها والاجتماعية ، السياسية منها والعسكرية .", "ان الاسلام حين يضع للغريزة ضوابط اخلاقية معينة فانما يفعل ذلك في ضوء تقديره لطبيعة الكائن البشري ولطبيعة احتياجاته العضوية والنفسية ، ولطبيعة متطلباته الروحية والبدنية ، تماما كما يفعل بالنسبة لغرائزه الأخرى ..", "وهنا بالذات يكمن السر في تفرد المنهج الاسلامي عن سائر المناهج الوضعية وفي قدرته على تنظيم الحياة الانسانية تنظيما دقيقاً يحفظ عليها انسانيتها ويقيها غوائل الانحراف والتطرف والشذوذ .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0022.png"}, {"n": 23, "paras": ["النظرية الجنسية في الإسلام", "ينظر الاسلام إلى الانسان نظرة شاملة .. ينظر اليه جسماً وعقلاً وروحاً . ينظر اليه من خلال تكوينه الفطري . ثم هو ينظم حياته ويعالجه على أساس هذه النظرة .. فالاسلام لم ينظر إلى الانسان نظرة ( مادية مجردة ) لا تتعدى هيكله الجسدي ومتطلباته الغريزية شأن المذاهب المادية ، في حين لم يحرمه حقوقه البدنية وحاجاته العضوية . لم يكن الاسلام ( ابيقوريا ) (١) في اطلاق الغرائز والشهوات من غير تنظيم ولا تكييف ، ولم يكن كذلك ( رواقيا ) (٢) في فرض المثاليات واعدام المتطلبات الحسية في الانسان .", "(١) نسبة إلى الفلسفة التي وضعها ابيقور عام ٣٤٣ ق م والتي تعتبر اللذة أساس الأخلاق ، وانها وحدها غاية الانسان وهي وحدها الخير ..", "(٢) نسبة إلى الفلسفة التي وضعها زينو القبرصي عام ٣٤٢ ق.م والتي تعتبر الشهوة شراً محضاً يجب إبادته .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0023.png"}, {"n": 24, "paras": ["يقول الأستاذ محمد قطب في كتابه (منهج التربية الاسلامية): ( الاسلام يؤمن من الكائن الانساني بما تدركه الحواس ، وبما يقع خارج نطاق الحواس .. يؤمن بكيانه المادي المحسوس ، وانه قبضة من طين الأرض .. يؤمن بما لهذا الكيان المحسوس من مطالب ويؤمن بما فيه من طاقات . ويعترف بهذا الكيان اعترافاً كاملاً لا يفض شيئاً من قيمته ولا يهدر شيئاً من طاقته ..", "يستجيب لحاجاته ومطالبه ، فيوفر له المأكل والملبس والمسكن والجنس ونصيبه من المتاع . ويجند طاقاته لتعمل في تعمير الأرض وانشاء النظم وتشييد الحضارات .", "وفي الوقت ذاته يؤمن بالكيان الروحي للانسان . يؤمن بأن فيه نفخة من روح الله .. ويؤمن بما لهذا الكيان الروحي من مطالب ، وما يشتمل عليه من طاقات . فيعطيه ما يطلبه من عقيدة ومثل وصعود وترفع ، ويجند طاقاته في اصلاح كيان النفس واصلاح شرور المجتمع ، واقامة الحق والعدل الأزلين ، بأن يصله بالله ..", "فحين توحي عقيدة من العقائد أو نظام من النظم بأنه ليس ثمة روح أو ليس ثم إله . وان"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0024.png"}, {"n": 25, "paras": ["الواقع المادي هو الحقيقة الوحيدة . وان الانتاج المادي والتنظيم الاقتصادي هو كل حياة البشرية .. حين ذلك تكبت مؤقتاً جوانب الانسان الروحية والوجدانية والفكرية .. وقد تذبل وتنحسر ويصيبها الشلل فتعجز عن النشاط ، ولكنها لا تبقى كذلك إلى الأبد ، وإلا مات الشعب وانقرض كما حدث لبعض الشعوب في التاريخ ..", "إن كل ما يصيب الأنسان في الحياة من شر ، كل ما يصيبه من قلق أو جزع أو اضطراب ، كل ما يصيبه من فساد أو بوار أو شقوة ، هو نتيجة حتمية لفقدان التوازن في داخل النفس ، وفقدانه من ثم في واقع الحياة ..", "حين تطغى على الأنسان شهوة من شهواته .. شهوة مال أو شهوة جنس أو شهوة قوة أو شهوة سلطان ، فذلك اختلال في باطن نفسه لا يسعده في الحقيقة وإن بدا له في أول الأمر انه مستمتع وراض وسعيد . إنما هو في الواقع في شقوة دائمة لأنه قلق على ما عنده وراغب في المزيد .. ثم هو اختلال في واقع الحياة . فكل شهوة زائدة عن الحد لا تجرف صاحبها وحده ، وإنما تصيب غيره من الناس في الطريق . تصيبهم بعدوان يقع عليهم لا محالة من هذه الشهوة التي تجاوز الحدود ) ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0025.png"}, {"n": 26, "paras": ["في نطاق هذا التصور لطبيعة الانسان ولاحتياجاته الفطرية ولضرورة تحقيق التوازن في اشباعاته النفسية والحسية ، يعتبر الاسلام الغريزة الجنسية إحدى الطاقات الفطرية في تركيب الانسان يجب أن يتم تصريفها والانتفاع بها في اطار الدور المحدد لها شأنها في ذلك شأن سائر الغرائز الأخرى ..", "ان استخراج هذه الطاقة من جسم الانسان ضروري ، كأن اختزانها فيه مضر وغير طبيعي ، ولكن بشرط الانتفاع بها وتحقيق مقاصدها الانسانية ..", "ان الفطرة جعلت في استخراج هذه الطاقة لذة ممتعة ، ولكنها لم تجعل هذه اللذة هدف الاستخراج المحض .", "ان من الأهداف التي يجب أن يحققها افراغ الشحنة الجنسية في الحياة الانسانية :", "١ - عقد أواصر المودة والرحمة بين الرجل والمرأة ، وهذا ما أشارت اليه الآية الكريمة ( ومن آياته أن خلق لكم من أنفسكم أزواجاً لتسكنوا اليها وجعل بينكم مودة ورحمة ) .", "٢ - تكوين الاسرة ، موطن الراحة والاستقرار ومصنع الأجيال والشعوب ، ومبتعث المسؤولية . فالرجل راع في بيته ومسؤول عن رعيته ، والمرأة راعية في بيتها ومسؤولة عن رعيتها ، وهما معاً راعيان في المجتمع ومسؤولان عن رعيتها ،"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0026.png"}, {"n": 27, "paras": ["ينشدان لها الخير ويحققان لها السعادة (ربنا هب لنا من ازواجنا وذرياتنا قرة أعين واجعلنا للمتقين اماما ) .", "٣ - استمرار النوع وتكاثر النسل وعمارة الحياة ، وهذه سنة الكون وفطرة الحياة التي فطر الله الناس عليها ..", "٤ - تحقيق النفعين الحسي والنفسي للانسان من افراغ الشحنة الجنسية ..", "هذه هي نظرية الاسلام إلى الجنس .. النظرة التي تستند إلى الاحاطة التفصيلية بطبيعة الانسان وبطبيعة خصائصه العضوية والنفسية .. وبالنتائج المترتبة عليها والغايات المقصودة منها ( لقد خلقنا الإنسان في أحسن تقويم ثم رددناه أسفل سافلين ، إلا الذين آمنوا وعملوا الصالحات فلهم أجر غير ممنون ) ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0027.png"}, {"n": 28, "paras": ["مكتبة المنارة الأزهرية"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0028.png"}, {"n": 29, "paras": ["الطريق الفطري للإشباع الجنسي", "مما تقدم يتبين لنا ان الإسلام يعترف بوجود الطاقة الجنسية في الكائن البشري ، كما يعترف بوجود طاقاته وغرائزه الأخرى الفطرية .. ولما كان الاسلام دين الفطرة فقد وضع النظام الفطري لتنظيم تصريف هذه الغريزة ..", "فهو من جانب لم يطلق لها العنان كما هو الحال في مذاهب الماديين ، كما انه لم يكبتها كما هو الحال في مذاهب المتقشفين والصوفيين المتطرفين . وانما كان موقفه حيالها موقفاً يحقق تصريفها والغاية الانسانية من تصريفها ضامناً بذلك صيانة المجتمع من الاضرار التي تنتج عن كل تصريف منحرف شاذ ..", "الزواج هو الطريق : لذلك كان الزواج في الاسلام الطريق الانساني الأخلاقي الأوحد الذي يؤدي إلى الاشباع الجنسي للفرد من غير اضرار"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0029.png"}, {"n": 30, "paras": ["بالمجتمع . بل كان الواحة الطبيعية الفطرية التي تجمع بين الرجل والمرأة وتمنحهما الراحة النفسية والحسية .. وكانت الآصرة المقدسة التي تتوالد عنها وتتزايد الأواصر والصلات المجتمعية الأخرى .. ان الاسلام ينظر إلى الإنسان على انه مستخلف في الأرض لعمارتها واشاعة الهدى والخير فيها ، وازالة الشر والبؤس عنها .. وان كل قواه وغرائزه وأفكاره وعواطفه يجب أن تسير في هذا الاتجاه ( قل ان صلاتي ونسكي ومحياي ومماتي لله رب العالمين ) ان الاسلام يعتبر الإنسان في الحياة موضع تجربة واختبار .. وانه سيبعث في الحياة الثانية لينال جزاءه . ( أفحسبتم انما خلقناكم عبثا وانكم الينا لا ترجعون ) .", "فالإنسان في نظر الإسلام مسؤول عن نفسه ، مسؤول عن جسده ، مسؤول عن غرائزه عن أعضائه .. مسؤول عن ذاته ومسؤول عن المجتمع من حوله في كل ذلك ( قل إن السمع والبصر والفؤاد كل أولئك كان عنه مسؤولا ) . ان عبودية الانسان الحقة لله لا يمكن أن تتحقق إلا بخضوعه كلية لله .. بخضوعه تفكيره ومشاعره وغرائزه للمنهج الذي أراده الله وجعله دين الفطرة ونظام الفطرة ، دين البشرية ونظامها من يوم ان قال ( اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينا ) . ان الإسلام يعمل على تكوين الإنسان الذي لا يعتبر الاشباعات المادية غاية بذاتها كائناً ما كانت ، وانما هي وسائل لتحقيق نتائج انسانية كريمة ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0030.png"}, {"n": 31, "paras": ["في ضوء هذه النظرة الخيرة الكريمة تصبح كل تصرفات الإنسان حق البسيطة منها جزئيات ينتظمها عقد واحد ويحدوها قصد واحد . انه السير مع الفطرة التي فطر الله الناس عليها .", "المفهوم الأساسي للزوجية (١) ان الزوجية في الحقيقة عبارة عن أن يكون شيء متصفاً بالفعل وآخر متصفاً بالقبول والانفعال .. ويكون في أحدهما التأثير وفي الآخر التأثر ، وفي هذا العقد وفي ذاك الانعقاد . وهذا الفعل والانفعال ، والتأثير والتأثر ، والعقد والانعقاد بين الشيئين هو علاقة الزوجية بينها . وهذه العلاقة هي أساس تركيب الأشياء في العالم وعلى هذا التركيب يجري نظام الكون .. فكل شيء في هذا الكون قد خلق زوجين وصنفين في طبقته .. وكل زوجين من الأزواج يرتبطان - من حيث المبدأ والأصل - بهذه العلاقة الزوجية التي يكون أحدهما فيه فاعلاً والآخر قابلاً ومنفعلا ..", "يقول الاستاذ محمد قطب في كتابه ( الانسان بين المادية والاسلام ) : يتصور الاسلام وجود علاقة بين الرجل والمرأة على انه الشيء الطبيعي الذي ينبغي أن يكون . فهو يقر بأن الله قد جعل في قلب كل منهما هوى للآخر وميلا اليه . ولكنه يذكرهما بأنهما يلتقيان لهدف هو حفظ النوع . وتلك حقيقة لا أحسبها", "(١) راجع كتاب الطلاق لأبي الأعلى المودودي ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0031.png"}, {"n": 32, "paras": ["موضع جدال . فمن المسلم به لدى ( العلم ) ان للوظيفة الجنسية هدفاً معلوماً . وليست هي هدفاً في ذاتها . فيقول القرآن ( نساؤكم حرث لكم ) فيحدد بذلك هدف العلاقة بين الجنسين ، بتلك الصورة الموحية ..", "وربما خطر في فكر سائل ان يقول : ان هدف الحياة من هذه الشهوة يتحقق سواء تيقظ اليه الفرد أو كان غارقاً في الشهوة العمياء ، فما الفرق إذن بين هذا وذاك ؟", "ولكن الحقيقة أن هناك فارقاً هائلا بين النظرتين في واقع الشعور : فحين يؤمن الانسان بأن للعمل الغريزي هدفاً اسمى منه ، وليس هو هدفاً في ذاته ، يخف سلطان الشهوة الطاغية في شعوره ، فلا يتخذ تلك الصورة الجامحة التي تعذب الحس أكثر مما تتيح له المتعة والارتياح . وليس معنى ذلك انه يقلل من لذتها الجسدية ولكنه على التحقيق يمنع الإسراف الذي لا يقف عند الحد المأمون ..", "ففي حدود الأسرة وفي نطاق الزواج يتيح الإسلام للطاقة الجنسية مجالها الطبيعي المعقول . ولكنه لا يتيح لها المجال في الشارع ، خلسة أو علانية ، وهو يرى ببصيرته كيف تنحل الأمم وتسقط حين تترك أفرادها يتهاوون في الرذيلة دون أن تأخذ بحجزهم وتمنعهم من الانحدار ..", "ويرى الدكتور فريديريك كين ان الزواج هو الطريق الصحيح لتصريف الطاقة الجنسية وهو الحل الأوحد الجذري"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0032.png"}, {"n": 33, "paras": ["للمشكلة الجنسية ، فيقول في كتابه ( حياتنا الجنسية ) : ( كان البشر في الماضي يتزوجون باكراً ، وكان ذلك حلاً صحيحاً للمشكلة الجنسية . أما اليوم فقد أخذ سن الزواج يتأخر كما أن هناك أشخاصاً لا يتوانون عن تبديل خواتم الخطبة مراراً عديدة فالحكومات التي ستنجح في نص قوانين تسهل بها الزواج الباكر ستكون الحكومات الجديرة بالتقدير لأنها تكتشف بذلك أعظم حل لمشكلة الجنس في عصرنا هذا ) .", "الاسلام يحض على الزواج وإذ يعتبر الاسلام الزواج الطريق الفطري الذي يحقق للطاقة الجنسية هدفها الانساني فضلاً عن تحقيقه اللذة الآنية منها فانه ينبري للحض على الزواج وتسهيله وتيسير أسبابه . وإلى أن تتهيأ للشباب فرص الزواج وأسبابه فان الإسلام يدعوهم إلى الاستعفاف وهو علاج مقبول وطبيعي في مجتمع نظيف خال من المثيرات مجتمع لا يترك الانسان فريسة القصف الغريزي المدمر ، كما هو مشاهد اليوم في المجتمعات البشرية كافة . فيقول الرسول ﷺ ( يا معشر الشباب من استطاع منكم الباءة فليتزوج ، فانه أغض للبصر ، وأحصن للفرج ، ومن لم يستطع فعليه بالصوم فانه له وجاء ) (١) ويقول ﷺ ( إذا تزوج العبد فقد استكمل نصف دينه فليتق الله في النصف", "(١) رواه البخاري ومسلم .", "الإسلام - ٣"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0033.png"}, {"n": 34, "paras": ["الباقي (١) ويقول ﷺ : ( ثلاث حق على الله عونهم : المجاهد في سبيل الله ، والمكاتب الذي يريد الأداء ، والناكح الذي يريد العفاف ) (٢) . وقال ( من كان موسراً لأن ينكح ثم لم ينكح فليس مني ) (٣) . وعن أنس بن مالك رضي الله عنه قال ( جاء رهط إلى بيوت أزواج النبي ﷺ يسألون عن عبادة النبي ﷺ ، فلما أخبروا كأنهم تقالوها . فقالوا . وأين نحن من النبي ﷺ وقد غفر الله له ما تقدم من ذنبه وما تأخر . فقال أحدهم . أما أنا فإني أصلي الليل أبداً وقال آخر : أنا أصوم الدهر ولا أفطر أبداً . وقال آخر : وأنا اعتزل النساء فلا أتزوج أبداً فجاء الرسول ﷺ اليهم فقال : أنتم القوم الذين قلتم كذا وكذا ؟ أما والله إني لأخشاكم لله ، واتقاكم له ، لكني أصوم وافطر ، وأصلي وارقد، وأتزوج النساء ، فمن رغب عن سنتي فليس مني ) (٤) .", "تعدد الزوجات مخرج مأمون والاسلام حين يضع نظاماً لتصريف الطاقة الجنسية ينظر إلى القضية من كافة جوانبها .. يلحظ وجود فوارق في القوى الجنسية بين الناس .. وهو لذلك يضع من التشريعات والمخارج ما يحقق الاشباعات الجنسية في نطاق الشرعية ..", "(١) رواه البيهقي .", "(٢) رواه الترمذي .", "(٣) رواه الطبراني .", "(٤) رواه البخاري ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0034.png"}, {"n": 35, "paras": ["إن نظام تعدد الزوجات في الاسلام ، ينطوي على حلول كثير من المشكلات .. فهو خير سبيل لسد الجوعات الجنسية لدى المتفوقين جنسياً الذين لا تكفيهم زوجة واحدة .. وخير لهؤلاء والمجتمع الذي يعيشون فيه ان تتعدد زوجاتهم من أن تتعدد خليلاتهم ؟ يقول الاستاذ يوسف القرضاوي في كتابه ( الحلال والحرام في الاسلام ) : ( ان الاسلام هو كلمة الله الأخيرة التي ختم بها الرسالات . ولهذا جاء بشريعة عامة خالدة تتسع للأقطار كلها وللاعصار قاطبة وللناس جميعاً .. انه لا يشرع للحضري ويغفل البدوي ، ولا للأقاليم الباردة وينسى الحارة ، ولا لعصر خاص مهملا بقية العصور .. انه يقدر ضرورة الأفراد وضرورة المجتمعات ويقدر حاجاتهم ومصالحهم جميعاً .. فمن الناس من يكون قوي الرغبة في النسل ولكنه رزق بزوجة لا تنجب لعقم أو مرض أو غيره. أفلا يكون أكرم لها وأفضل أن يتزوج عليها من تحقق له رغبته مع بقاء الأولى وضمان حقوقها ؟ ومن الرجال من يكون قوي الغريزة ثائر الشهوة ، ولكنه رزق بزوجة قليلة الرغبة في"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0035.png"}, {"n": 36, "paras": ["الرجال . أو ذات مرض ، أو تطول عندها فترة الحيض ، أو نحو ذلك . والرجل لا يطيق الصبر كثيراً عن النساء . أفلا يباح له أن يتزوج بأخرى حليلة بدل أن يبحث عنها خليلة ؟ هذا هو تعدد الزوجات الذي أنكره الغرب المسيحي على المسلمين وشنع عليهم ، على حين أباح لرجاله تعدد العشيقات والخليلات بلا قيد ولا حساب ، ولا اعتراف بأي التزام قانوني أو أدبي نحو المرأة أو الذرية التي تأتي ثمرة لهذا التعدد اللاديني أو اللا أخلاقي .. فأي الفريقين أقوم قيلا وأهدى سبيلا ؟ ( وقد ثبت ان الخيانة الزوجية في الأمم القائلة بالاقتصار على زوجة واحدة تزيد باضطراد . فقد دلت الاحصاءات الرسمية التي نشرت على ان عدد قضايا الزنى في فرنسا سنة ١٨٨٠ أصبح تسعة أمثال ما كان عليه سنة ١٨٢٦(١)) .", "العلاقة الحسيه بين الزوجين ان الاسلام كمنهج حياة لم يغفل أو يهمل حق دقائق وتفصيلات السلوك البشري الخاص والعام لتكون متوافقة ومنسجمة مع القواعد الاعتقادية والأخلاقية التي جاء لتحقيقها وتعميقها .", "(١) حضارة الغرب صفحة ٤٨١ ترجمة المرحوم عادل زعيتر ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0036.png"}, {"n": 37, "paras": ["لذلك نجد أن الاسلام وضع للعملية الجنسية ( الجماع ) ما تحتاجه من توجيه وتنظيم .. فهو يدرك ان ( الجماع ) كما يكون مثالياً محققاً الغاية الفطرية منه يجب أن يكون منسجماً في العمل والاستجابة ، مؤدياً إلى الاستمتاع والاتحاد الحسين والنفسيين بين الزوجين . والاستعداد النفسي والتحضير العاطفي خير سبيل للبلوغ بالزوجين معاً الاشباع المطلوب .. وإلى ذلك يشير الرسول ﷺ بقوله : ( لا يقعن أحدكم على امرأته كما تقع البهيمة ، وليكن بينهما رسول قيل وما الرسول يا رسول الله؟ قال: القبلة والكلام)(١). ويقول عليه الصلاة والسلام : ( ثلاث من العجز في الرجل: الأول أن يلقى من يحب معرفته فيفارقه قبل أن يعلم اسمه ونسبه. والثاني : أن يكرمه أحد فيرد عليه كرامته . والثالث : أن يقارب الرجل جاريته أو زوجته فيصيبها قبل أن يحدثها ويؤانسها )(٢) . وقد ورد حول هذا المعنى كلام للامام الغزالي في كتابه (احياء علوم الدين ) جاء فيه : ( ثم إذا قضى وطره فليتمهل على أهله حتى تقضي هي أيضاً نهمتها . فان انزالها ربما يتأخر فيهيج شهوتها. ثم القعود عنها إيذاء لها. والاختلاف", "(١) و (٢) رواه الديلمي في مسند الفردوس ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0037.png"}, {"n": 38, "paras": ["في طبع الانزال يوجب التنافر مهما كان الزوج سابقاً إلى الانزال . والتوافق في الانزال ألذ عندها (١) .", "ان الاتحاد الحسي والنفسي الذي يحرص الاسلام على تحقيقه بين الزوجين اثناء الجماع له فوائده الكثيرة التي لا تخفى على من لهم إلمام في العلوم النفسية والجنسية . ويكفي انه يضمن الاشباع الكامل للطرفين مما يتحقق معه احصانهما وتوثيق عرى الحب والمودة بينهما ..", "ان كثيراً من الدراسات الجنسية الحديثة تشير إلى أن الانحرافات والخيانة والمشاكل التي تصيب الحياة الزوجية انما تعود في معظم الحالات إلى عدم التجانس الجنسي والنفسي بين الزوجين ، وعدم بلوغهما درجة الاتحاد ..", "قدسية العلاقات الزوجية", "وإذا كان الاسلام يحرص على تحقيق التكامل في العلاقات الجنسية بين الزوجين ، فانه يحرص كذلك على احاطة هذه العلاقات بسياج من القدسية والسرية .. حفاظاً على المروءة والشرف وصيانة للفرد والمجتمع مما تسببه المجاهرة من أخطار واضرار تقوض الفضائل الانسانية ..", "(١) احياء علوم الدين - أدب المعاشرة - صفحة ٥٠ ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0038.png"}, {"n": 39, "paras": ["ولذلك حذر الاسلام الأزواج من ممارسة الجنس علانية ، أو جعله موضع أحاديثهم وسرهم . فقال ﷺ : ( شر الناس منزلة عند الله يوم القيامة الرجل يفضي إلى المرأة وتفضي اليه ثم ينشر سرها ) (١) .", "وعن أبي هريرة رضي الله عنه قال : صلى بنا رسول الله ﷺ فلما سلم أقبل علينا فقال : ( مجالسكم . هل منكم الرجل إذا أتى أهله اغلق بابه وأرخى ستره ، ثم يخرج فيحدث فيقول : فعلت بأهلي كذا وفعلت بأهلي كذا ؟ فسكتوا .. فأقبل على النساء ، فقال : هل منكن من تحدث ؟ فجثت فتاة كعاب على أحدى ركبتيها وتطاولت ليراها رسول الله ﷺ ويسمع كلامها . فقالت : أي والله . انهم يتحدثون وانهن يتحدثن . فقال عليه السلام هل تدرون ما مثل من فعل ذلك ؟ ان مثل من فعل ذلك مثل شيطان وشيطانة لقي أحدهم صاحبه بالسكة فقضى حاجته منها والناس ينظرون اليه ) (٢) .", "(١) رواه مسلم وابو داود .", "(٢) رواه احمد وابو داود ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0039.png"}, {"n": 40, "paras": ["مكتبة الجامعة الإسلامية بالمدينة المنورة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0040.png"}, {"n": 41, "paras": ["الاسلام والانحرافات الجنسية", "ان من ملامح التكامل في المنهج الاسلامي معالجاته الجذرية لقضايا الفرد والمجتمع ، سواء بالتربية أو بالترهيب والترغيب ، أو بالعقوبة . فالاسلام يضع تشريعاته في ضوء تصوره العميق لطبيعة الناس وقدراتهم ، ولعوامل الخير والشر النافذة فيهم ، مبيناً ما يضرهم وما ينفعهم وما يسعدهم وما يشقيهم .. فهو لا يتركهم إلى ذواتهم ، ولا يكلهم إلى نزواتهم .. إنه يحدوهم دائماً وأبداً إلى صراط العزيز الحكيم .. يحضهم على الخير والطهر ، ويحذرهم وينذرهم من مغبة الانسياق مع الهوى واتباع غير سبيل المؤمنين .", "الاسلام يحذر من الزنا إن الاسلام يدرك أن الزنا طريق منحرف لتصريف الطاقة الجنسية لما يؤدي من اختلاط الأنساب وانهيار الأسر والمجتمعات"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0041.png"}, {"n": 42, "paras": ["وانتشار الأمراض ، وطغيان الرذائل ، واندثار الفضائل . ولذلك جاء التحذير منه شديداً والتحريم له أكيداً ، فقال تعالى: ( ولا تقربوا الزنا انه كان فاحشة وساء سبيلا ) وقال تعالى : ( والذين لا يدعون مع الله إلها آخر ولا يقتلون النفس التي حرم الله إلا بالحق ولا يزنون ومن يفعل ذلك يلق أثاماً، يضاعف له العذاب يوم القيامة ويخلد فيه مهانا ) . وجاء عن النبي ﷺ انه قال : ( يا معشر المسلمين اتقوا الزنا فان فيه ست خصال . ثلاث في الدنيا وثلاث في الآخرة . فأما التي في الدنيا : فذهاب بهاء الوجه ، وقصر العمر ، ودوام الفقر .. وأما التي في الآخرة : فسخط الله تبارك وتعالى ، وسوء الحساب ، والعذاب بالنار ) . ويقول عليه الصلاة والسلام ( لا تزال أمتي بخير ما لم يفش فيهم ولد الزنا فإذا فشا فيهم ولد الزنا فأوشك ان يعمهم الله بعذاب ) . والاسلام حين يسوق هذه النذر القرآنية والنبوية ترهيباً من الزنا وتنفيراً منه ، فلكونه يدرك مدى ما يلحقه بالفرد والمجتمع من أخطار واضرار ومهالك .", "مضار الزنا الصحية : لقد بات في حكم المؤكد - طبياً - ان الزنا يتسبب في كثير من الأمراض والأوبئة الفتاكة والتي تتفاوت في خطورتها ومضاعفاتها .. يقول الدكتور جون بيستون :"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0042.png"}, {"n": 43, "paras": ["( ان القرائن التي جمعت من عدة دراسات تقول ان الأمراض الجنسية معظمها تنتج من العلاقات الجنسية خارج نطاق الزواج ) . ويقول الدكتور كلود سكوت نيكول : ( ان المشكلة التي تواجهنا اليوم هي تبدل قيمنا الأخلاقية التي شجعت وتشجع أقامة العلاقات الجنسية المحرمة . وهذه بدورها سببت ازدياداً حاداً في اصابات الأمراض الناتجة عن الاباحة الجنسية ) . من هذه الأمراض :", "مرض السيفلس : وهو مرض جرثومي ينتج عن جرثومة تتخذ شكل (برغي) تعرف باسم ( سبيروشيت ) والطريقة الشائعة للاصابة تتم من خلال العملية الجنسية المحرمة ( الزنا ) . وتنفذ جرثومة السيفلس إلى الجسم من خلال جرح متقرح أو من خلال منطقة مصابة في الجسم ثم تنمو وتكبر . وهذا المرض هو واحد من أخطر الأمراض التي عرفها الانسان . فالجهاز العصبي ينهار ، ويصاب المريض بالعمى وبالشلل وبالحطاط عام في صحته وقد تمتد الجرثومة إلى أي جزء من جسده لتصيب عظامه وتنخرها ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0043.png"}, {"n": 44, "paras": ["مرض التعقيبة أو السيلان وهذا المرض وان كان أقل خطراً نسبياً على الانسان من السيفلس الا انه غير مرغوب فيه على الاطلاق . وتتم الاصابة بهذا المرض عن طريق الجامعة المحرمة ( الزنا ) . ومن أعراض هذا المرض: حدوث ألم وحرقة شديدة عند التبول . تجمع مواد صفراء على الفرج داخل الحشفة يتولد عنها رائحة كريهة .. بالاضافة إلى التهابات أخرى قد يتسبب بها هذا المرض .. ومرض التعقيبة قد يؤدي إلى العقم من خلال اقفال ( فاس ديفيرنس ) كما ان العطب قد يمتد إلى الأعضاء التناسلية الأخرى. وقد تصاب القناة البولية عند الرجل بقروح تؤدي إلى انحباس البول .. لا أجد نفسي بحاجة للاسهاب كثيراً عن هذه الأمراض لأن المكتبات تمتلىء بالكتب الطبية التي تتحدث عنها .. وحسبي في هذه العجالة ان أنقل إلى القراء نتيجة الدراسة التي وضعتها هيئة الصحة العالمية والتي تبين مدى تصاعد الخط البياني لحوادث الأمراض الزهرية وذلك ما بين عام ١٩٥٠ - ١٩٦٠ حيث مسحت فيها ( ١٠٥ ) دول وكانت كما يلي :", "المنطقة | عدد الدول الممسوحة | الدول المصابة افريقيا | ٢٩ دولة | ٢٣ دولة اميركا | ٢١ دولة | ١٥ دولة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0044.png"}, {"n": 45, "paras": ["شرقي البحر المتوسط ١٢ دولة ٦ دول جنوب شرقي آسيا ٢٣ دولة ١٣ دولة أوروبا ٢٠ دولة ١٩ دولة المجموع ١٠٥ دول ٧٦ دولة", "مضار الزنا الاجتماعية ثم ان الآثار المترتبة عن الزنا اجتماعياً واخلاقياً قد تفوق خطورة الأمراض الزهرية ، فكيف بالاثنتين معاً ؟ يقول العلامة أبو الأعلى المودودي(١) : ان الزنا عدوان على الفطرة البشرية في التآلف والزواج والسكنى والطمأنينة والاستقرار . فالزاني يتعود على التذوق والتغيير ، وهذا عكس ما يرجى للعلاقات الزوجية الصحيحة بين الرجل والمرأة ، فلن يكون انسجام ولا وفاء ولا حسن معاملة ولا ثقة ولا طمأنينة ولا راحة بال بين الزوجين . هذا إذا لم يعزف الزاني عن الزواج كلياً تهرباً من التبعات والمسؤوليات . وهذا تخريب ظاهر للمجتمع الذي يعتمد على الفرد أولاً والأسرة ثانياً .. ومن البديهي ان وجود الزنا يستلزم أيضاً وجود ابناء السفاح الذين يولدون عن غير رغبة أو قصد ، والعدوان والظلم يقعان عادة على المولود نفسه ، ثم على التمدن الانساني بصورة عامة ..", "(١) راجع كتاب الحجاب للاستاذ أبي الأعلى المودودي ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0045.png"}, {"n": 46, "paras": ["يقول الدكتور كلود سكوت نيكول ( وهؤلاء الأطفال غير الشرعيين يربون عادة في مؤسسات أو عند عائلات غريبة ، ولهذا السبب بالذات ينشأون معقدي الشخصية منحرفي النفسية ) .", "والزنا يستلزم وجود البغاء ووجود طبقة بائسة من النساء اللواتي يمثلن اسفل طبقات المجتمع في الذل والمهانة ونقص الاعتبار وهذا متناقض قطعاً مع فكرة المساواة والعدالة والأخوة الانسانية في المجتمع . فبدل ان يكن من النساء الشريفات والأمهات الفاضلات وربات البيوت المحصنات والمربيات الكريمات تراهن كالمراحيض يستعملن لقضاء وطر كل خليع داعر ، يكسبن عيشهن ببيع أجسادهن لكل زائر ، ويقضين أعمارهن في هذا الدنس بدل ان يقمن بخدمة نافعة مثمرة في المجتمع .", "يقول الطبيبان ( باتشار وموريل ) : ( ان انتشار الأمراض الزهرية راجع بالأساس إلى اباحية الصلات الجنسية وكل شيء يفتت شمل الأسرة يزيد في هذه الاباحية والأمراض . يذهب الوالدان للعمل خارج البيت تاركين الأولاد والمراهقين ليعتنوا بأنفسهم وهذا يؤدي بدوره إلى ضعف الصلات العائلية وهبوطاً للمستويات الأخلاقية . فلقد ارتفعت نسبة الفتيات اللواتي يمارسن الصلات الجنسية قبل الزواج حتى أصبحت تقريباً تماثل نسبتها في الشباب . وهذا تطور محزن في مجال المساواة بين الجنسين(١).", "(١) راجع كتاب الامراض الجنسية للدكتور نبيل الطويل ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0046.png"}, {"n": 47, "paras": ["الاسلام يحذر من اللواط : اللواط هو ممارسة الرجل الجنس مع رجل آخر ، إما بممارسة العادة السرية ، أو بواسطة الدبر ، أو بواسطة الفم .. وتتحدث التقديرات عن وجود عشرات الملايين من الرجال الذين يمارسون اللواط في العالم .. بينهم ثلاثة ملايين في الولايات المتحدة الأميركية لوحدها ..", "وتعود أصل التسمية باللواط إلى قوم لوط الذين فشا فيهم هذا الداء الوبيل ، فاستحقوا نقمة الله وعذابه . وقد حكى القرآن الكريم قصتهم حيث قال : ( إذ قال لهم أخوهم لوط ألا تتقون ، إني لكم رسول أمين فاتقوا الله وأطيعون ، وما أسألكم عليه من أجر إن أجري إلا على رب العالمين .. أتأتون الذكران من العالمين وتذرون ما خلق لكم ربكم من أزواجكم بل أنتم قوم عادون . قالوا لئن لم تنته يا لوط لتكونن من المخرجين . قال : إني لعملكم من القالين رب نجني وأهلي مما يعملون . فنجيناه وأهله أجمعين ، إلا عجوزاً في الغابرين ، ثم دمرنا الآخرين ، وأمطرنا عليهم مطراً فساء مطر المنذرين ) .", "ويلاحظ كذلك أن بعض الكتاب يستعملون كلمة (صادومية) للتعبير عن اللواط .. وهذه الكلمة مشتقة كما يبدو من اسم ( صدوم ) احدى مدن قوم لوط التي شاع فيها هذا الشذوذ الآثم فأحرقها الله وجعل عاليها سافلها . ويذكر المؤرخون أنها تقع في قاع البحر الميت أو بحيرة لوط .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0047.png"}, {"n": 48, "paras": ["واللواط شذوذ بالغ عن الفطرة ، يمجه الذوق السليم وتأباه المروءة والرجولة والكرامة .. انه انحراف هائل ومريع عن قوانين الطبيعة وناميسها . فلا عجب بعدئذ أن يكون موقف الاسلام من هذه العادة الشنيعة المرذولة موقفاً صارماً وزاجراً .. يبدو أولاً في العقاب الرباني لقوم لوط ( فلما جاء أمرنا جعلنا عاليها سافلها وأمطرنا عليها حجارة من سجيل ) . كما يبدو من خلال أحاديث كثيرة للرسول ﷺ منها قوله : ( أخوف ما أخاف عليكم قوم لوط . ولعن من فعل فعلهم ثلاثاً ، فقال : لعن الله من عمل عمل قوم لوط ، لعن الله من عمل عمل قوم لوط ، لعن الله من عمل عمل قوم لوط ) (١) وقوله : ( أربعة يصبحون في غضب الله ويمسون في سخط الله قلت من هم يا رسول الله ؟ قال : المتشبهون من الرجال بالنساء ، والمتشبهات من النساء بالرجال ، والذي يأتي بهيمة ، والذي يأتي الرجال ) (٢) . تأويلات وتفسيرات : ان كثيراً من العلماء والمؤرخين يعتقدون بأن اللواط لم يعرف قبل أهل ( سدوم ) وانه بتفشي هذه الظاهرة الشاذة فيهم لجأت نساؤهم إلى ممارسة السحاق فيما بينهن ليقمعن شهوتهن ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0048.png"}, {"n": 49, "paras": ["وفي نطاق التفسير العلمي لظواهر الميل لذات الجنس أبدى العلماء نظريات متعددة ابرزها ان الرجولة والانوثة الكاملة هما افتراض عقلي لا وجود له في الواقع . وان التجارب العلمية تؤكد أن هنالك نسبة رجولة في النساء ونسبة أنوثة في الرجال وان هذه النسب وتفاوتها في كلا الطرفين هي الحوافز الطبيعية للشذوذ ..", "والحقيقة ان الشذوذ وان كانت له ثمة مبررات خلقية ( تكوينية ) إلا ان الأسباب الجوهرية الكامنة وراءه والباعثة عليه إنما هي أسباب نفسية وتربوية ..", "إن الغريزة لدى الانسان أيا كانت قابلة أصلا لحالتي الاستقامة والشذوذ .. والتربية هي التي تلعب الدور الكبير في تحديد طبيعة تصريفها ..", "ان انحراف التربية وانعدام الحس الديني، وفساد الأخلاق من شأنها جميعاً أن تهيء الأجواء والمناخات المناسبة للانحراف والشذوذ .", "ان الفراغ والترف وتميع مواقف القوانين الوضعية من الجرائم الأخلاقية والجنسية من الأسباب الرئيسية الكامنة وراء ظواهر الشذوذ الجنسي ..", "ثم اننا وان سلمنا بصحة النظرية العلمية التي سقناها في نطاق تفسير الميل ( لذات الجنس ) فما هي التفسيرات العلمية يا ترى لأنواع أخرى لا حصر لها من أنواع الشذوذ ، كإتيان", "٤٩ الإسلام - ٤"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0049.png"}, {"n": 50, "paras": ["البهيمة (١) والسحاق (٢) والكلف بالأشياء (٣) والسادية (٤) والماسوشية (٥) وغيرها ؟", "انه ليس لدينا من تفسير لهذه الظواهر الشاذة إلا انها وليدة نفوس وتصورات مربضة مشوهة سقيمة .. وفي المجتمع السليم لا يمكن بحال وجود مثل هذه الآفات ، ولئن وجدت ففي نطاق ضيق ومحدود ثم لا تلبث أن تستأصل ..", "انه حصاد سوء التصور لطبيعة الوظيفة الجنسية ، واعتبار المتعة الناتجة عنها هي الأساس كائناً ما كان الأسلوب أو الطريق؟", "العادة السرية :", "العادة السرية أو الاستمناء هي تصريف الطاقة الجنسية عن طريق مداعبة الأعضاء التناسلية .. وهذه العادة يلجأ اليها المراهقون - ذكوراً واناثاً - في مطلع نضجهم الجنسي في حال انعدام التربية والتوجيه السليمين .. وقد سميت بالعادة السرية لأن ممارستها تتم غالباً في الخفاء والسرية .", "ويقدر العلماء أن نسبة ممارسة هذه العادة مرتفعة وبخاصة", "(١) مجامعة الحيوانات .", "(٢) مجامعة النساء للنساء .", "(٣) إتيان الجنس عن طريق أشياء محددة قد تكون أحياناً ملابس نسائية داخلية .", "(٤) الحصول على اللذة من خلال التعرض للعذاب والآلام .", "(٥) شبيهة بالسادية ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0050.png"}, {"n": 51, "paras": ["لدى الشباب الذين تتراوح أعمارهم بين الثالثة عشرة والخامسة عشرة ، بينما تهبط النسبة بعد هذا السن لاعتبارات وأسباب متعددة ..", "وإذا كان بعض العلماء والأطباء لا يرون بأسا أو ضيراً من ممارسة هذه العادة ، إلا ان عدداً آخر من هؤلاء يرى انها تؤدي إلى أضرار صحية كثيرة .. بل ان بعضهم يؤكد ان ادمانها يولد أنواعاً من الأمراض أهمها : انحطاط جسدي وعقلي - حب الشباب - ضعف النظر - تقوس الكتفين - هبوط الوزن - العجز الجنسي - وقف نمو الجسم . إلى غير ذلك ..", "ومما تجدر الاشارة اليه في هذا المقام هو ان ممارسة العادة السرية لم تعد مقصورة على الشباب الذين لا يملكون متنفساً طبيعياً لتصريف طاقتهم الجنسية .. بل ان هذه العادة غدت لوناً من ألوان الشذوذ يمارسه المنحرفون والاباحيون والمهوسون جنسياً صغاراً وكباراً ، ذكوراً واناثاً ، افرادياً وجماعياً ، سراً وعلانية ..", "ومن هنا كان لا يمكن معالجتها بحال كظاهرة من ظواهر التهييج الذاتي كما يحاول أن يفعل بعض العلماء والأطباء والفقهاء وكما ذهب إلى ذلك مذهب الامام أحمد بن حنبل الذي اعتبر المني فضلة من فضلات الجسم يجوز اخراجه ، وإن قيد فقهاء الحنابلة الجواز بأمرين : خشية الوقوع في الزنى ، وعدم استطاعة الزواج .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0051.png"}, {"n": 52, "paras": ["اننا وان سلمنا جدلاً بأن العادة السرية حالة طبيعية يمر بها الانسان في مرحلة معينة من عمره ، غير اننا لا يمكن اعتبارها كذلك عندما تصبح ممارستها لذاتها أو كوسيلة تنويع .", "ان سد منافذ الشذوذ والانحراف من الأساس هو الاسلوب الأسلم في التربية .. وان تحويل النظر دائماً وأبداً إلى الطريقة الطبيعية الفطرية لتصريف الطاقة الجنسية يصرف التفكير بما عداها .. وهذا ما ذهب اليه أكثر العلماء والفقهاء الذين اعتبروا كل وسيلة أو علاقة جنسية خارج الزواج حراماً قطعاً مستدلين بقول الله تعالى ( والذين هم لفروجهم حافظون إلا على أزواجهم أو ما ملكت أيمانهم فإنهم غير ملومين ، فمن ابتغى وراء ذلك فأولئك هم العادون ) .", "ان تعهد المجتمع بالتربية الصحيحة والتوعية السليمة .. وان تنظيف حياة الناس من كل ما يستثير غرائزهم .. وان تنظيم تصريف الأوقات والطاقات فيما يعود على الفرد والمجتمع بالنفع والخير .. كل ذلك وغيره من شأنه أن يكسر حدة الانحراف والشذوذ في واقع الحياة .. وخاصة إذا رافقه التشجيع الفعلي على الزواج بما في ذلك توفير أسبابه وايجاد التسهيلات اللازمة لتحقيقه ..", "تقول الدكتورة ( ماري وود آلن ) في كتابها ( ما لا يجب أن تجهله كل فتاة : ( أولاً يجب ان تستبدلن اتجاهكن العقلي في كل ما"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0052.png"}, {"n": 53, "paras": ["يتعلق بالجنس .. يجب ان تعتبرن الجنس مقدساً وخاصاً بأرفع الوظائف الجسدية ، أعني وظيفة التناسل . كما يجب أن تعترفن بأن هذه الوظيفة عندما يسيطر عليها العقل تصبح ينبوعاً للقوة عند الفرد. فلنطهر فكرنا من كل صورة شريرة ، ولنملأه بالأفكار الطاهرة . ثم لنأخذ أنفسنا بالحياة المستقيمة .. احسن أيتها الفتيات إلى انفسكن احساناً حقيقياً فانظرن إلى الهدف الذي تسعين اليه في بدء كل عمل .. وكن دائماً سيدات لحواسن لا عبدات لها ) ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0053.png"}, {"n": 54, "paras": ["العقوبة في الإسلام وسيلة تربوية وبناء", "العقوبة في النظام الاسلامي وسيلة من الوسائل التي يعتمدها الاسلام لصيانة المجتمع من غوائل الانحراف والشذوذ .. لتأديب الجاني وللترهيب من الجناية .. للاقتصاص من المجرم وللحد من الجريمة ..", "فالاسلام كما سبق واشرنا يضع من التشريعات والقوانين والاجراءات الاحترازية والزجرية والتربوية ما يضمن سلامة المجتمع وسلامة الافراد من شتى الجرائم والمحاولات الجرمية بما يتناسب وطبائع الناس كافة ..", "فمن الناس من يكفيه النصح والتذكير ومن الناس من يلزمه التأنيب والتعزير .. ومنهم من لا ينفع معه سوى العقوبة الزاجرة والقصاص الرادع .", "( فالعقوبات موانع قبل الفعل زواجر بعده ، أي العلم بشرعيتها يمنع الاقدام على الفعل ، وايقاعها بعده يمنع من العودة اليه ) (١) .", "(١) فتح القدير صفحة ١١٢ ج ٤ ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0054.png"}, {"n": 55, "paras": ["يقول الماوردي : ( الحدود زواجر وضعها الله تعالى للردع عن ارتكاب ما حظر وترك ما أمر ، لما في الطبع من مغالبة الشهوات الملهية عن وعيد الآخرة بعاجل اللذة . فجعل الله تعالى من زواجر الحدود ما يردع به ذا الجهالة حذراً من ألم العقوبة وخيفة من نكال الفضيحة . ليكون ما حظر من محارمه ممنوعاً وما أمر به من فروضه متبوعاً ، فتكون المصلحة اعم والتكليف أتم(١) .", "إن طبيعة العقوبات الاسلامية وموافقتها لنوعية الجرائم المحددة لها ، لها بالغ الأهمية في حصول الأثر النفسي الرادع عن ارتكاب الجريمة ..", "ان الاسلام في تقريره لنوعية العقوبة يحرص على حماية الأخلاق بل يصدر عن هذا الحرص أساساً حين تقريرها ، وهذا أساس الخلاف في النظر إلى الجريمة وتصورها بين الاسلام وبين القوانين الوضعية جمعاء .. فالقوانين الوضعية تهمل المسائل الأخلاقية اهمالاً شبه تام .. فهي لا تعاقب على الزنا مثلاً إلا في حالة الاكراه .. بمعنى ان الزنا في تصور القوانين الوضعية ليس جرماً بذاته وإنما الجرم في الاكراه أو في تناول الأجر عليه ، أما إذا حصل بالتراضي وبدون أجر فلا ضير في ذلك ؟ ثم ان هذه القوانين لا تعاقب على شرب الخمرة أو على السكر لذاته ، وانما تعاقب", "(١) الماوردي صفحة ٢١٣ ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0055.png"}, {"n": 56, "paras": ["( المشمول ) حين يخرج وهو في حالة السكر الشديد إلى الشارع لاحتمال تعرض الناس لايذائه ؟", "يقول الاستاذ الشهيد عبد القادر عوده : ( والعلة في استهانة القوانين الوضعية بالاخلاق ان هذه القوانين لا تقوم على أساس من الدين ، وإنما تقوم على أساس الواقع وما تعارف الناس عليه من عادات وتقاليد . والقواعد القانونية الوضعية يضعها عادة الافراد الظاهرون في المجتمع بالاشتراك مع الحكام وهم يتأثرون حين وضعها بأهوائهم وضعفهم البشري ونزعاتهم الطبيعية إلى التحلل من القيود .. كذلك فان هذه القواعد قابلة للتغيير والتبديل بحسب أهواء القائمين على أمر الجماعة . فكان من الطبيعي أن تهمل القوانين الوضعية المسائل الأخلاقية شيئاً فشيئاً وان يأتي وقت تصبح فيه الاباحة هي القاعدة والأخلاق الفاضلة هي الاستثناء . ولعل البلاد التي تطبق القوانين الوضعية قد وصلت هذا الحد الآن ) (١) .", "(١) راجع التشريع الجنائي في الاسلام ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0056.png"}, {"n": 57, "paras": ["لمحة عن عقوبات الجرائم الجنسية", "عقوبة الزنا : للزنا في الشريعة الاسلامية ثلاث عقوبات هي : الجلد - التغريب - الرجم . أما الجلد والتغريب فللزاني غير المحصن لقوله تعالى ( الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة ولا تأخذكم بهما رأفة في دين الله إن كنتم تؤمنون بالله واليوم الآخر . وليشهد عذابهما طائفة من المؤمنين ) ولقوله ﷺ ( البكر بالبكر : جلد مائة وتغريب عام )(١) . وأما عقوبة الرجم فللزاني المحصن لقوله ﷺ ( لا يحل دم امرىء مسلم يشهد أن لا إله إلا الله وأن محمداً رسول الله الا باحدى ثلاث : الثيب(٢) الزاني - والنفس بالنفس - والتارك لدينه المفارق الجماعة .", "عقوبة اللواط : يجمع العلماء على اعتبار اللواط زنا . وان اختلفوا نسبياً في تحديد العقوبة .", "(١) التغريب : النفي .", "(٢) الثيب : المتزوج ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0057.png"}, {"n": 58, "paras": ["فمذهب الامام مالك يرى ان عقوبة اللواط الرجم مطلقاً سواء كان الفاعل أو المفعول به محصنين أو غير محصنين(١) . وفي مذهب الشافعي وأحمد ثلاثة آراء :", "١ - ان اللواط حكمه حكم الزنا ، فيعاقب اللائط والموطوء بعقوبته . فمن كان محصناً رجم ومن لم يكن محصناً جلد وغرب.", "٢ - ان اللائط هو الذي يرجم أما الملوط به فلا يرجم وإنما يجلد ويغرب في كل الأحوال ..", "٣ - ان عقوبة اللائط والملوط به القتل في كل حال(٢) .", "عقوبة السحاق : ممارسة السحاق متفق على تحريمه في الإسلام لنص الآية الكريمة : ( والذين هم لفروجهم حافظون إلا على أزواجهم أو ما ملكت أيمانهم فإنهم غير ملومين، فمن ابتغى وراء ذلك فأولئك هم العادون ) ولقول الرسول ﷺ : ( لا ينظر الرجل إلى عورة الرجل، ولا المرأة إلى عورة المرأة ، ولا يفضي الرجل إلى الرجل في ثوب واحد، ولا تفضي المرأة إلى المرأة في الثوب الواحد)(٣) ولقوله ﷺ ( اذا أتى الرجل الرجل فهما زانيان ، واذا أتت المرأة المرأة فهما زانيتان ) (٤) . وعقوبة هذه الجريمة الشاذة التعزير ..", "(١) شرح الزرقاني .", "(٢) نهاية المحتاج .", "(٣) رواه احمد ومسلم وأبو داود والترمذي .", "(٤) راجع نيل الأوطار ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0058.png"}, {"n": 59, "paras": ["عقوبة وطء البهائم : يعتبر وطء البهائم والحيوانات عند الامامين مالك وأبي حنيفة معصية وفيها التعزير ، وكذلك الحكم في تمكين المرأة حيواناً من نفسها (١) . أما في مذهب الشافعي وأحمد فيعتبر زنا ويعاقب عليه بالقتل في كل الأحوال لما ورد عن الرسول ﷺ (. من أتى بهيمة فاقتلوه واقتلوا البهيمة ) (٢) . وفي الحقيقة ان طبيعة العقوبات التي وضعتها الشريعة الاسلامية من شأنها ان تستأصل شأفة الرذيلة من المجتمع في حين تعمل العقوبة المائعة في القوانين الوضعية بصورة غير مباشرة على تشجيع الرذائل والانحرافات الجنسية لأن هذه العقوبات في الواقع لا تؤلم المنحرفين أو تخيف مرتكبي الفاحشة ولا تحملهم على ترك فعلتهم والإقلاع عنها .. بل انها لا تستثير في نفوسهم من العوامل المضادة ما يكبح جماحهم عن اتيان الفواحش والموبقات أياً كانت ..", "(١) شرح الزرقاني .", "(٢) رواه أحمد وابو داود والترمذي ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0059.png"}, {"n": 60, "paras": ["للإباحة الجنسية وآثارها على المجتمعات البشرية", "كل من يستقرىء أحوال الأمم والشعوب على مدار التاريخ متلمساً أسباب الوهن والضعف ، وعوامل التفكك والانهيار ، وبواعث الهزيمة والانكسار فيها ، يدرك مكان الانحرافات الأخلاقية والفوضى الجنسية من تلك الأسباب والعوامل والبواعث .. لقد بات في حكم اليقين ان طغيان الجنس في مجتمع ما من المجتمعات هو أقوى معاول الهدم فيه ..", "الجنس يبدد الثروة القومية : ان طغيان الرذائل والفواحش والمثيرات في المجتمع يلحقها بشكل عفوي شيوع الترف والتبذير والبذخ واهدار الأموال وتفتيت الثروات وتبديدها فيما يعود على الناس بأوخم العواقب. وبذلك تضيع على الأمم والشعوب طاقات وامكانيات كان يمكن الافادة منها في مجالاتها الخيرة كالصناعة والزراعة والعمران وسواها من المجالات التي تحقق لها الرقي والتقدم والرفاه .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0060.png"}, {"n": 61, "paras": ["ان عشرات الملايين من سائر العملات في العالم تنفق يومياً على ( الجنس ) وعلى كل ما يتصل به من قريب أو بعيد . ويكفي ان نقدم هنا صورة من صور البذخ التي يعيشها بعض الأفراد والمجتمعات في نطاق الثورة الجنسية المحمومة التي تشهدها البشرية لندرك النتيجة الحتمية والنهاية المفجعة التي تنتظر هؤلاء ان عاجلاً أو آجلاً ؟", "يقول ( كافارلكيس ) الرجل الذي كتب عقد زواج ( اوناسيس ) ملك البترول اليوناني على ( جاكلين كندي ) في كتابه ( سر الاعتراف ) والذي كشف فيه عن اسرار وفضائح مذهلة ( ان جاكلين لم تشأ أن تكون كباقي الزوجات ، أي أن تقول لزوجها اعطني أنا نازلة للسوق .. بل حددت في البند الثاني مرتباً شهرياً يبلغ ٢٧٠ الف دولار ( حوالي ٧٥٠ الف ليرة لبنانية ) .. وهذا المرتب كما يقول البند هو لشراء الأزياء والأحذية والجوارب وأدوات الزينة والتجميل ومصاريف ( الكوافير ) . من ذلك ان جاكلين كنيدي نزلت إلى شارع ( اوبير ) المتفرع من حي الأوبرا ، فلم تتركه إلا بعد ان انفقت فيه قرابة خمسين الف دولار ، على الملابس الداخلية والخارجية وادوات الزينة والشعر المستعار ) .", "الجنس يقوض الصحة العامة :", "وإذا كانت الفوضى الجنسية تصيب الأمم في ثرواتها وأموالها فانها كذلك تلحق بالافراد والمجتمعات الاسقام والعلل مما يعود"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0061.png"}, {"n": 62, "paras": ["بأوخم العواقب على الصحة العامة .. يقول الدكتور ( ليريد ) وهو طبيب فرنسي ( انه يموت في فرنسا ثلاثون الف نسمة بأمراض الزهري المختلفة كل عام ) . هذا ويموت في اميركا بين ثلاثين وأربعين الف طفل بمرض الزهري الموروث كل سنة .", "الجنس يهدم الاواصر المجتمعية ومن حصاد الاباحة والفوضى الجنسية تهدم الأسر وتفكك الوحدات المجتمعية ، وتمزق اواصر القربى ، وتقطع صلات الرحم .. فالأسرة كما هو معلوم بداهة ركن المجتمع واحدى قواعده الرئيسية . والاسرة هي موطن الاستقرار والاطمئنان ومبعث تنظيم العلاقات والنوازع والتصرفات .. وهي الواحة الفطرية والدائرة الطبيعية لتربية الأجيال تربية متوازنة سليمة لا تعقيد فيها ولا انحراف .. فحين يعزف الأفراد عن الزواج ، ويمارسون بطريقة وبأخرى تصريف طاقاتهم الجنسية ، يتقوض بالتالي نظام العائلة، ويفقد المجتمع أحد أركانه .. في حين تعصف فيه شق الوان الانحراف والشذوذ كما هو مشاهد اليوم في المجتمعات الغربية بصورة خاصة ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0062.png"}, {"n": 63, "paras": ["الجنس يخرب الأخلاق الانسانية ومن مظاهر التخريب في المجتمعات الاباحية تهدم الأخلاق والصفات الانسانية وبروز النزعات البهيمية كالانانية والنفعية والتمرد واللامبالاة إلى ما لا نهاية له .. ان علامات التخريب هذه بادية بوجه خاص في المجتمعات الأوروبية والأمريكية حيث انتشرت ظواهر الوجودية والهيبية ومظاهر التمرد والانعتاق من كل القيود الاجتماعية ، والتفلت من كل المسؤوليات ، وبالتالي خروج كل التقاليد والقيم والقوانين ؟ ان ملايين من الشبان والفتيات يعيشون اليوم عالة على مجتمعاتهم وأممهم لا يتحملون أدنى مسؤولية .. يعيشون على السرقة والقتل والمخدرات والجنس .. يعيشون اشباحاً أو شبه اشباح ، وحيوانات وأكثر من حيوانات ؟", "النتيجة : حين تبتلى أمة من الأمم بمثل هذه الآفات بسبب تفحشها وتهتكها .. حين تتبدد ثروتها ، وتتهدم أخلاقها ، وتنفصم أواصرها .. وحين تجتاحها الأمراض الفتاكة تكون قد فقدت مقومات وجودها ، وأسباب بقائها واستمرارها ، ومن ثم تكون قد حكمت على نفسها بالاعدام .. والتاريخ البشري يؤكد هذه الحقيقة .. يؤكدها قديماً ويؤكدها حديثاً . يؤكدها قديماً حين يكشف عن أسباب"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0063.png"}, {"n": 64, "paras": ["انهيار الامبراطوريات . ويؤكدها حديثاً حين يبحث في اسباب هزائم الجيوش والدول ..", "يقول الكاتب الفرنسي ( اندريا موروا ) في كتابه ( أسباب انهيار فرنسا في الحرب العالمية الثانية ) : ( من أهم أسباب انهيار فرنسا هو تفسخ الشعب الفرنسي نتيجة لانتشار الرذيلة بين أفراده ) . وهذا ما حدا بالجنرال ديغول في أعقاب تسلمه زمام السلطة لأن يستدعي رئيس شرطة باريس ويقول له : ( اغلق لي هذه المواخير وأوكار الخنافس في عاصمتي ) .", "والعرب لم يصلوا في تاريخهم الحديث ، والحديث جداً إلى ما وصلوا اليه من ضعف واستخذاء، ولم يصابوا بما أصيبوا به من هزائم وانتكاسات الا بانحراف معتقداتهم ، بقوامة الالحاد والفكر المادي على حياتهم ، بطغيان المجون والتهتك والرذيلة في مجتمعاتهم ..", "ان كثيراً من الوثائق تؤكد ان الخلفيات التي تكن وراء هزائم العرب المتكررة أمام اسرائيل وبخاصة هزيمة عام ١٩٦٧ والتي تسببت بتدمير القوات الجوية المصرية وسقوط الجولان واحتلال سيناء والضفة الغربية ، انما تتصل بهذه الأسباب المشار اليها(١) .", "ولذلك كان بديهياً ان يأتي حرص الاسلام شديداً - في نطاق", "(١) راجع الكتب التالية : - تحطمت الطائرات عند الفجر - طريق النصر في معركة النار ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0064.png"}, {"n": 65, "paras": ["الاعداد والاستعداد - على صيانة الناس من كل عوامل الهزيمة والانهيار ، وعلى بعث الثقة في نفوسهم ، على رفع الروح المعنوية في صفوفهم . على تنظيف حياتهم الخاصة والعامة من كل انحراف ومعصية .", "ان الاسلام يدرك ان المعصية عنوان ، وان الرذيلة سبب الذل والمهانة ، وان العزة لا تكون إلا بالطاعة والتعفف والطهر ..", "ان نظرة سريعة إلى التاريخ الاسلامي ، إلى الأسباب التي مكنت الجيوش الاسلامية من اجتياح امبراطوريتي فارس والروم والسيطرة على أكثر من نصف المعمورة في أقل من ربع قرن تؤكد مدى اهتمام الاسلام باخلاقية الفرد والمجتمع في حالتي السلم والحرب ، والتي عبر عنها الرسول ﷺ بقوله : ( إنما بعثت لأتمم مكارم الأخلاق ) .", "تذكر كتب التاريخ انه عندما استبطأ عمر بن الخطاب فتح مصر كتب إلى عمرو بن العاص وكان قائداً على الجيش الاسلامي يقول ( أما بعد : فقد عجبت لابطائكم عن فتح مصر ، تقاتلونهم منذ سنتين وما ذاك الا لما أحدثتم وأحببتم من الدنيا ما أحب عدوكم . وإن الله تبارك وتعالى لا ينصر قوماً إلا بصدق نياتهم ) .", "وفي وصية له إلى سعد بن أبي وقاص قائد الجيوش الاسلامية إلى فارس يقول ( أما بعد فاني أوصيك ومن معك من الأجناد بتقوى الله على كل حال ، فان تقوى الله أفضل العدة على العدو وأقوى المكيدة في الحرب . وأمرك ومن معك من الأجناد أن", "٦٥ الإسلام - ٥"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0065.png"}, {"n": 66, "paras": ["تكونوا أشد احتراساً من المعاصي منكم من عدوكم ، فان ذنوب الجيش أخوف عليهم من عدوهم ، وانما ينصر المسلمون بمعصية عدوهم . ولولا ذلك لم تكن لنا بهم قوة ، لأن عددنا ليس كعددهم ، ولا عدتنا كعدتهم . فان استوينا في المعصية كان لهم الفضل علينا في القوة ، والا ننصر عليهم بفضلنا ، لم نغلبهم بقوتنا . واعلموا ان عليكم في سيركم حفظة من الله يعلمون ما تفعلون ، فلا تعملوا بمعاصي الله وأنتم في سبيله . ولا تقولوا إن عدونا شر منا فلن يسلط علينا وان أسأنا فرب قوم سلط عليهم شر منهم كما سلط على بني اسرائيل لما عملوا بساخط الله كفرة المجوس فجاسوا خلال الديار وكان وعداً مفعولا ) .", "وجاء في كتاب ( طريق النصر في معركة الثأر ) للواء الركن محمود شيت خطاب قوله :", "( الذي أعلمه علم اليقين، ولا شك فيه أبداً ، هو أن الملوث جنسياً أو الملوث جيبياً ، لا يمكن أن يقاتل في الحزب كما يقاتل الرجال ..", "وأريد بالملوث جنسياً ، الذي تردى في مهاوي الرذيلة فسقاً وفجوراً ، يقضي أيامه مفكراً في البغايا ، ويقضي لياليه في معاشرتهن ، ويكشف ذيله على ما حرم الله ويطمع في أعراض الناس .", "وأقصد بالملوث جيبياً ، الذي دخل جيبه المال الحرام رشوة وغشاً وجمعاً للمال من غير طريق مشروع .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0066.png"}, {"n": 67, "paras": ["وأقرر هذا المبدأ اعتماداً على تجربتي العملية في الحروب واستناداً إلى دراساتي لتاريخ الفتح الاسلامي العظيم ، وإلى ما قرره القادة العظام الأقدمون والمحدثون على حد سواء )", "وهذا ما قرره أبو بكر الصديق رضي الله عنه حين قال : ( ما ترك قوم الجهاد في سبيل الله إلا ضربهم الله بالذل ، ولا تشيع الفاحشة في قوم قط إلا عمهم الله بالبلاء ) ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0067.png"}, {"n": 68, "paras": ["أنوثتها أبشع استغلال ، وتعطلت وظيفتها الفطرية في الحياة ، وغدت متاعاً أو شبه متاع . ان تحرر المرأة المزيف في المدنية الغربية جعلها تتحرر حتى من واجباتها كزوجة ، من واجباتها كأم ، من واجباتها كمربية أجيال وصانعة رجال .. ان هذه المدنية الزائفة جعلت المرأة تقتحم ميدان كل عمل.. ميدان الصناعة والزراعة والفن والتجارة وغيرها من الميادين مما يتعارض في كثير من الأحيان مع تركيبها العضوي وطاقاتها الجسدية والنفسية .. كل ذلك على حساب مسؤوليتها الأصيلة في نطاق الزوجية والأمومة .. ان الفاجعة الكبرى في العالم الاسلامي ان تسلك نساؤه نفس الطريق الذي سلكته المرأة الأجنبية وتتبع خطاها خطوة خطوة ، اتباع انقياد واقتداء .. مبهورة بالأضواء والضوضاء ، مفتتنة بالزينة والمساحيق والعطور ، مصروعة بحمى الأزياء والملابس الفاضحة .. وليت المرأة في عالمنا الاسلامي تدرك الحقيقة . ليتها تستطلع وضع المرأة الأجنبية بدون أضواء ومن غير ( روتوش ) تستطلع وضعها النفسي . وحينذاك ستدرك انها في شقاء وتعاسة وقلق لا تحسد عليه .. ليت المرأة في عالمنا الاسلامي تقرأ وتطالع وتتطلع على ما يكتبه عقلاء الغرب وعلماؤه وأطباؤه عن النكبات والمآسي التي خلفتها الحضارة الغربية وتخلفها في حياة الناس هناك ؟؟"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0068.png"}, {"n": 69, "paras": ["صرح البروفسور دكتور ( كلين ) رئيس أطباء مستشفى حكومي في المانيا ، وذلك في مؤتمر للأطباء عقد هناك ، قال : ( ان نسبه كبيرة وكبيرة جداً من النساء في مجتمعنا لسن سعيدات في حياتهن . والسبب في ذلك هو المتطلبات الجسمية والروحية المتصاعدة . وعلى هذا فانني أعلن النفير العام لعلم الطب . ان الواجب على ( المجلس البلدي ) ان ينظر إلى هذه الفاجعة التي تحل بكثير من نسائنا العاملات بعين الجد والاعتبار . ان هذا الخطر يهدد كثيرين منا ، لأن هذا معناه انهيار عظيم وخسارة مزدوجة لملايين من البشر ) .", "ويعالج الكاتب الاجتماعي ( ج - س - بولاك ) أزمة الحضارة الغربية ، وما خلفته من شقاء وبؤس في الفرد والمجتمع فيقول : ( اننا نلاحظ منذ سنوات ان عصرنا يفقد بالتدريج حرارة الحياة فيه ، ويخسر باطراد الدفء والطمأنينة من القلب البشري . فحياة الفرد لا تعرف الارتباطات والواجبات الاجتماعية كما عرفها انسان الأمس . لم يعد المرء يشعر نحو جواره بذلك الشعور الذي كان معروفاً في الماضي . كما أن روابط الأسرة لم تعد كما كانت ، بل فقدت كثيراً من مقوماتها . اننا في الحقيقة وسائل للميكانيكية التي غيرت كل الروابط الاجتماعية حتى روابط الأسرة .. اننا ويا للأسف ندفع طائعين ثمناً لما يعطينا"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0069.png"}, {"n": 70, "paras": ["التطور التكتيكي من أدوات .. اننا نعاني خسارة مطردة في مادتنا الروحية دون أن نشعر ) . وليت المرأة في شرقنا الاسلامي تطلع على التقارير التي تضعها السلطات في الدول الغربية حول حوادث الانتحار المتزايدة بين النساء بسبب القلق والشقاء واليأس الذي يعشن بين براثنه .. ان أحد هذه التقارير يشير إلى أن أكثر من ٥٠٠٠ حادثة انتحار وقعت في انكلترا خلال سنة واحدة . ويكفي للمبهورات بالأضواء من نسائنا أن يطلعن على الرسالة التي كشفها التحقيق في قضية انتحار ( مارلين مونرو ) أشهر ممثلة اغراء ، والمحفوظة في صندوق الامانات في ( مانهاتن بنك في نيويورك ) والتي تلقي بعض الأضواء على الأسباب التي دفعت هذه المرأة وهي في أوج شهرتها وقمة مجدها الفني إلى الانتحار.. تقول ( مارلين مونرو ) في رسالتها تلك : ( احذري المجد . احذري ما يخدعك بالأضواء .. اني أتعس امرأة على هذه الأرض . لم استطع أن أكون أماً . اني امرأة أفضل البيت ، الحياة العائلية الشريفة الطاهرة . بل ان هذه الحياة العائلية هي رمز سعادة المرأة بل الانسانية . لقد ظلمني الناس . وان العمل في السينا يجعل المرأة سلعة رخيصة تافهة مهما نالت من المجد والشهرة الزائفة ) . ان الدراسات المستفيضة حول أزمة الحضارة الغربية وما"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0070.png"}, {"n": 71, "paras": ["جرته على المجتمعات البشرية من بؤس وشقاء وتعامة ، وما ألحقته بالمرأة - على وجه الخصوص - من إيلام وإيذاء . وما أوصلتها اليه من مهانة وضعة ، كفيلة بأن تؤكد ان هذه الحضارة في النزع الأخير ، وان الأمل في نشوء حضارة انسانية روحية اخلاقية تحفظ على المرأة طهرها وكرامتها ، وتقلدها وظيفتها الرفيعة في الحياة ..", "المرأة في الحضارة الاسلامية :", "مقابل تلك المكانة الوضيعة المرذولة التي أوصلت الحضارة الغربية المرأة اليها .. مقابل ذلك الاستغلال الرخيص لها .. تبدو المرأة في الاسلام وقد احتلت مكانتها الاصيلة في الحياة . المكانة التي تحفظ عليها كرامتها .. المكانة التي تؤهلها للقيام بدورها الانساني الكبير في تربية الاجيال ..", "لقد أراد الاسلام للمرأة أن تكون في نطاق ( الزوجية ) المرأة التي تهب الأنس والمتعة لزوجها ، وتوفر السعادة والهناء لبيتها واسرتها ..", "وأرادها أن تكون في نطاق ( الأمومة ) الأم الحانية والمربية الواعية . تصنع من صغارها رواد مستقبل وأبطال غد وأرادها الاسلام في نطاق المجموعة البشرية أن تكون رائدة اصلاح ، وداعية خير وصلاح .. أرادها مرشدة وموجهة ومعلمة .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0071.png"}, {"n": 72, "paras": ["ان وظيفة المرأة في الاسلام في مستوى وظيفة الرجل أهمية .. وكذلك مسؤوليتها أمام الشرع . وهذا ما نطقت به الشواهد التاريخية جيلا بعد جيل . لقد كان للمرأة المسلمة دورها الكبير إلى جانب الرجل في اقامة المجتمع المسلم وبناء الحضارة الاسلامية .. شاركته اعباء حمل دعوة الاسلام ، فتعلمت وعلمت وتفقهت وفقهت .. شاركته كل صنوف المحن وألوان الاضطهاد في سبيل الله .. امتحنت فصبرت ، وابتليت فثبتت . وشاركته أخطار الحروب ، ومعامع القتال ودروب الجهاد، وابلت بلاء حسناً .. لم تكن المرأة دفينة بيتها كسقط المتاع كما يظن البعض كما انها لم تكن منطلقة على وجهها راكبة رأسها بدون حد أو قيد كما يراد لها اليوم .. تقول الكاتبة الشهيرة ( آنا رورد ) في مقالة نشرتها في جريدة ( الاسترن ميل ) : ( لئن تشتغل بناتنا في البيوت خوادم أو كالخوادم خير وأخف من اشتغالهن في المعامل . حيث تصبح البنت ملوثة بأدران تذهب برونق حياتها إلى الأبد . ألا ليت بلادنا كبلاد المسلمين فيها الحشمة والعفاف والطهر رداء .. الخادمة والرقيق يتنعمان بأرغد عيش"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0072.png"}, {"n": 73, "paras": ["ويعاملن كما يعامل أولاد البيت ، ولا تمس الاعراض بسوء .. نعم انه لعار على بلاد الانجليز أن تجعل بناتها مثلا للرذائل بكثرة مخالطة الرجال . فما بالنا لا نسعى وراء ما يجعل البنت تعمل بما يوافق فطرتها الطبيعية ، من القيام في البيت وترك أعمال الرجال للرجال سلامة لشرفها ) ويقول ( جول سيمون ) في مجلة المجلات الفرنسية : ( المرأة التي تشتغل خارج بيتها تؤدي عمل عامل بسيط ولكنها لا تؤدي عمل امرأة ؟ )"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0073.png"}, {"n": 74, "paras": ["المنهج الإسلامي في المجتمع من الانحراف والتحلل", "ينفرد الإسلام عن الاتجاهات الأخرى في تصوره للمعاني الأخلاقية .. لأسلوب تعميق هذه الأخلاق في كيان الفرد | والمجتمع .. لبواعث الانحراف .. لأسباب طغيانه .. لكيفية مواجهة هذه البواعث والأسباب . للفعاليات والعوامل الكفيلة بصيانة الحياة من كل ما يهدد انسانيتها ، من كل ما يهبط بقيمتها الأخلاقية ..", "والمنهج الاسلامي في تصوره هذا يحيط احاطة كاملة بطبائع الاشياء كلها .. بطبائع الافراد والمجتمعات .. بطبائع تركيب الافراد - ذكوراً واناثاً - وبطبائع تركيب المجتمعات .. ومن خلال هذا التصور المتكامل لطبيعة كل شيء يضع الانسان قواعد السلوك الاجتماعي ، ضوابطه ، مقوماته .", "ولسنا نحن في هذا النطاق بصدد مناقشة نظرية الإسلام الاجتماعية واستعراض نظامه الاجتماعي .. وانما الذي يعنينا من كل ذلك استخلاص ابرز القواعد التي يعتمدها الاسلام لصيانة الحياة الاجتماعية ، وبخاصة فيما يتعلق منها ( بالجنس ) موضوع هذا الكتاب .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0074.png"}, {"n": 75, "paras": ["في القواعد التربوية : يحرص الاسلام أول ما يحرص في نطاق صيانة المجتمع وتوفير السلامة له على تكوين الافراد وتربيتهم واعدادهم لمواجهة مغريات الحياة ومفاتنها بصلابة وثبات .. وللوصول إلى هذا المستوى من الثبات والصلابة في الحق والتورع والتعفف عن مساخط الله، يعمد الاسلام إلى اقامة رقابة ذاتية في أعماق النفس البشرية تحصنها من نزعات الشر ودوافع الهوى، يعمد الاسلام إلى استنهاض مقومات الخير في الناس وتنميتها فيهم ليكتسبوا المناعة ضد ما يعترض حياتهم من جراثيم وأوبئة اجتماعية .. ان التربية الاسلامية من شأنها ان تحقق لكل فرد - على الزمن - قوامته على نفسه ، وسلطانه العقيدي على نوازعه وغرائزه ، حيث تعاف نفسه تلقائياً اتيان المنكرات والخبائث دونما حاجة إلى رقابة شرطي أو سوط جلاد ؟", "١ - التربية الروحية وغايتها عقد الصلة الدائمة بين الانسان وبين الله في كل لحظة من اللحظات تحقيقاً لاستقامة حياة الانسان وخضوعها للمنهج الاسلامي في جميع تفريعاتها وتفصيلاتها . ان شعور الانسان بأن الله قريب منه ، يسمعه ويراه ، يحصي سيئاته وحسناته ، يبعث في نفسه الرهب والرغب والاطمئنان .. الرهب من مخالفة الله وعصيانه ، والرغب"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0075.png"}, {"n": 76, "paras": ["في رحمته ورضوانه ، والاطمئنان إلى عدله وإحسانه والقرآن الكريم يشير إلى هذه المعاني في كثير من المواقع ، منها قوله تعالى: ( أرأيت ان كان على الهدى ، أو أمر بالتقوى ، أرأيت إن كذب وتولى ، ألم يعلم بأن الله يرى ؟ ) وقوله ( أم يحسبون أنا لا نسمع سرهم ونجواهم ، بلى ورسلنا لديهم يكتبون ) وقوله ( وهو الله في السموات والأرض يعلم سركم وجهركم ويعلم ما تكسبون) ( ولقد خلقنا الانسان ونعلم ما توسوس به نفسه ونحن أقرب إليه من حبل الوريد ) .", "ومن أجل بعث هذه الصلة ، من أجل تحقيق هذه المعاني في أعماق الانسان. شرع الاسلام العبادة لتنظيم وتنمية هذا العروج الروحي الذي يرتقي بالانسان دائماً إلى الأعلى ويدفعه دوما إلى الأسمى .. ( ان الصلاة تنهى عن الفحشاء والمنكر ) ( من لم تنهه صلاته عن الفحشاء والمنكر لم يزدد من الله إلا بعداً ) .", "ان العبادة في مدلولها الحقيقي وفي مردودها الأصيل هي بعث للطاقة الروحية التي توقظ القلب وتحييه وتجعله يمارس وظيفته الهادية في حياة الانسان", "ان حياة القلب ويقظته حياة النفس ويقظتها ، حياة الضمير ويقظته . وان موت القلب وغفلته موت الضمير وغفلته وانعدام الخير وانطفاء النور في أعماق النفس البشرية . وصدق رسول الله ﷺ حيث يقول ( ان في الجسد مضغة اذا صلحت صلح الجسد كله واذا فسدت فسد الجسد كله ، ألا وهي القلب ) وإلى هذا المعنى يشير الشاعر :"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0076.png"}, {"n": 77, "paras": ["رأيت الذنوب تميت القلوب وقد يورث الذل ادمانها وترك الذنوب حياة القلوب وخير لنفسك عصيانها ان التربية الروحية في مقاصدها الأساسية تهدف إلى إيجاد النفسية المسلمة المتكاملة .. إلى تحقيق ( الكيفية الإسلامية ) التي يمارس الانسان بها غرائزه وميوله ونزعاته جميعاً ..", "٢ - التربية الفكرية", "وتهدف التربية الفكرية في الاسلام إلى تركيز مفاهيم الاسلام وأحكامه لدى الناس لتجري تصرفاتهم على أساسها ، بحيث يصبح الاسلام عندهم مقياس كل قضية ، وفصل كل خطاب ، وحل كل مشكلة ، وزمام كل أمر . ( فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ، ثم لا يجدوا في أنفسهم حرجاً مما قضيت ويسلموا تسليما ) . ان الاسلام منهج حياة .. ان استقامة حياة الانسان في اتباع هذا المنهج والصدور عنه في كافة الشؤون والأحوال . ولذلك كانت معرفة هذا المنهج وحسن تدبره واستيعابه شرط الاتباع وأساسه . وصدق رسول الله ﷺ حيث يقول ( من يرد الله به خيراً يفقهه في الدين ) : ان سلوك الانسان مرتبط بوعيه ، صادر عن تصوراته ومفاهيمه في معظم الاحيان . ولهذا فان من شأن التربية الفكرية ان تمنح الانسان القدرة على التمييز بين الغث والثمين"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0077.png"}, {"n": 78, "paras": ["بين الصالح والطالح بين الخير والشر بين الحلال والحرام . كما ان من شأنها أن تهيء عقله ليكون الطاقة الواعية التي تحدوه إلى الخير . تعرفه به ، وتلزمه باتباعه .", "وعندما تتهيأ للانسان القدرة على المعرفة والتمييز يغدو قادراً على توجيه خطاه والسير في الطريق السوي وصدق الله تعالى حيث يقول ( انما يخشى الله من عباده العلماء ) ويقول الرسول ﷺ ( من سلك طريقاً يلتمس فيه علماً ، سهل الله له طريقاً إلى الجنة (١)) .", "ان أحكام الإسلام أحاطت بكل شؤون الحياة صغيرها وكبيرها ، بينت طبيعتها ، وميزت بين خبيثها وطيبها ليسهل على المرء مجانبة الخبيث بدون مشقة ولا اعنات . وهذا معنى قوله ﷺ ( الحلال بين والحرام بين ، وبينهما أمور مشتبهات لا يعلمهن كثير من الناس . فمن اتقى الشبهات فقد استبرأ لدينه وعرضه . ومن وقع في الشبهات وقع في الحرام . كالراعي يرعى حول الحمى يوشك أن يقع فيه . الا وإن لكل ملك حمى . ألا وإن حمى الله محارمه . ألا وإن في الجسد مضغة إذا صلحت صلح الجسد كله ، وإذا فسدت فسد الجسد كله ، ألا وهي القلب (٢))", "(١) رواه مسلم .", "(٢) متفق عليه ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0078.png"}, {"n": 79, "paras": ["٣ - التربية الجسدية", "وتهدف هذه التربية إلى تمكين التكوين العضوي في الانسان من القيام بوظيفته ، من توجيه الطاقة الحيوية فيه ، وفق الأطر الفكرية والروحية التي وضعها الاسلام . ليتحقق بذلك التجانس والتوافق في حياة الانسان وليتحقق أثر التوازن بين مدارك عقله وموحيات قلبه ونوازع بدنه ..", "ان من معطيات التوافق في منهج التربية الاسلامية بين تصور الانسان وتصرفه أن يصبح لهذا التصرف قيمة .. قيمة تفوق حدود التصرف نفسه .. تتعدى اللذة الناتجة عنه . قيمة تتوازى وتتساوى مع القيم الروحية والفكرية سواء في واقع الحياة أو في ميزان الآخرة .. كل ذلك من غير انقاص لأثر اللذة نفسها أو فائدة التصرف ذاته .", "وبذلك يتحقق لفت الانسان إلى قيمة جسده .. إلى وظيفة هذا الجسد . إلى وظيفة كل عضو من اعضائه .. ومن ثم إلى مسؤوليته في حفظ هذه القيمة وصيانتها ، وإلى مسؤوليته في تحقيق هذه الوظيفة لأعضائه . وهذا سر معنى قوله ﷺ ( إن لبدنك عليك حقاً ) وقوله في الحديث القدسي ( وما يزال عبدي يتقرب إلي بالنوافل حتى أحبه . فاذا أحببته كنت سمعه الذي يسمع به ، وبصره الذي يبصر به ، ويده التي يبطش بها ، ورجله التي يمشي بها .. الحديث )"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0079.png"}, {"n": 80, "paras": ["وقد اعجبني ما ساقه الأستاذ محمد قطب حول هذا المعنى في كتابه ( منهج التربية الاسلامية ) حيث يقول : ( فحين يقول انسان لنفسه : انني أحس في أعماقي بحنين إلى الجنس الآخر ، ورغبة قوية في اللقاء بأحد أفراده ، والامتزاج معه ، والافضاء اليه ، والاتحاد الكامل معه حتى كأننا شخص واحد لا شخصان منفصلان .. هذا الاحساس ليس عيباً في ذاته ولا قذارة . انه فطرة الله التي فطر الناس عليها . كل الرجال وكل النساء يشعرون بهذا الحنين وهذه الرغبة . ولا بد ان يشعروا بها ليحققوا غاية الحياة ويحفظوا النوع على وجه الأرض. والتركيب الجسمي يشير إلى هذه الوظيفة . ففيزيولوجياته وبيولوجياته وكياوياته كلها مهيأة للقيام بهذه الوظيفة على وجهها الأكمل ، لتنتج أجيالاً جديدة من الحياة ، وهو أمر لا يتم بغير لقاء زوجين . وحين أحس بهذا الأحساس وهذا الميل ، فأنا سائر مع الفطرة في اتجاهها السليم . ولكن ليس معنى هذا أن يكون التفكير في مسائل الجنس هو شغلي الشاغل ، وهمي المقعد المقيم . فالحياة ليست جنساً خالصاً ، ولا هي محصورة في هدف واحد . ان علي تبعات أخرى تجاه نفسي وتجاه الناس . علي أن أتعلم . وعلي أن انتج . وعلي أن أنظر في أمر المجتمع : الاسلام - ٦"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0080.png"}, {"n": 81, "paras": ["أسائر هو على ما ينبغي له أم منحرف عن سبيله . وما أسباب انحرافه . وعلي أن أقوم بدوري في تقويمه من انحرافه . وخير وسيلة لذلك هي القدوة . فينبغي أن أكون أنا بذاتي قدوة حسنة . وإلا فلا قيمة لكل ما أقول من أقوال . وأنا أقول للناس ان الذي يفسدهم هو انحرافهم في طريق الشهوات . فلأكن أنا المثل في عدم الانحراف مع الشهوات .", "وكذلك ليس معنى هذا ان أخطف فتاة ما لأقضي معها رغبة الجنس فهذه الفتاة ليست لي . لا أملكها لنفسي حق أتصرف في شأني وشأنها على هذا الوضع . ان لها عرضاً يكافىء عرضي لا يجوز لي أن ادنسه . اني أحب ان يكون عرضي نظيفاً طاهراً لم يدنسه شيء . فلأحافظ على عرض هذه الفتاة كذلك . وأني احب حين تكون لي زوجة ان تكون نظيفة ان تكون خالصة لي . بروحها وجسمها جميعاً . فلأترك هذه الفتاة اذن نظيفة لمن ستكون زوجاً له ، فلأتركها له خالصة كما احب ان تكون زوجتي لي ..", "ولو انها رضيت رضاء بأن اقضي معها رغبة الجنس أو دعتني هي إلى ذلك فلا فارق . انه لا يجوز لي .. انها كالحارس الذي يدعو الناس إلى سرقة المال الذي يحرسه فذلك لا يعطي الناس الحق في السرقة ، لأن الحارس لا يملك المال في الحقيقة . وهذه الفتاة الحارسة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0081.png"}, {"n": 82, "paras": ["على عرضها لا تملك التصرف فيه ولا دعوة الناس إلى اغتصابه . انه ليس عرضها وحدها انه عرضها وعرض والديها وعرض أسرتها وعرض مجتمعها ، وعرض الإنسانية إنه عرض الأمانة التي ائتمن الله عليها البشر وينبغي أن يردوا له الأمانة نظيفة كما تلقوها ، كاملة كما تسلموها إلا بحقها الذي نص عليه صاحب الحق . وليس معنى هذا كذلك ان تكون صورة الجنس في حسي وفي تفكيري هي صورة الجسد الهائم الشهوان ، فأنا لست جسداً خالصاً ، ولا تمر علي لحظة واحدة في حياتي أكون فيها جسداً بلا عقل . أو جسداً بلا روح ، وإنما أنا دائماً وفي كل لحظة جسد وعقل وروح . واحساسي بالجنس هو قطعة مني ، هو جزء من كياني كله ، فلا كن اذن على الفطرة السليمة لبني البشر . فليكن إحساسي بالجنس شاملاً لكياني كله ، شاملاً لكل ما أنا مشتمل عليه من مشاعر . فليكن رغبة جسم ، وخفقة قلب ، ورقة روح . فليكن عاطفة . فليكن إلى جانب الرغبة مودة ورحمة وتعاطفاً وتفاهماً وامتزاجاً روحياً، ولقاء يرتفع بالكيان إلى عليين. ولن يتأتى ذلك وأنا أتناوله خلسة في الظلمة ، أو سرقة من الحارس الذي لا يملك التصريح . وقد تأتي علي لحظة يخيل إلي فيها ان هذه الخلسة المختلسة تحقق كياني كله ، وترتفع بي - في وهمي - إلى حيث اريد أن أكون . ولكنها مشاعر"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0082.png"}, {"n": 83, "paras": ["الرغبة هي التي تخيل ذلك . فلأنظر إلى الأمر في غير ساعة الرغبة لأدرك الحقيقة . أو . فلأنظر لخلسة يختلسها شخص غيري . ما رأيي فيها ؟ هل اصدقه لو قال انها نظيفة وسامية ؟ هل أقبلها في أهلي ؟؟", "كلا ! ليس معنى احساسي بالجنس شيئاً من هذا كله . وإنما أنا أحس بتلك الرغبة الفطرية واستجيب لها على طريقة الانسان . الانسان الذي يملك تصرفه ويختار طريقه لا على طريقة الحيوان الذي لا يملك التصرف ولا يختار الوسيلة ، ولا يعرف غير ما تمليه عليه فيزيولوجياته وبيولوجياته وكيماوياته . لأنه جسد بغير عقل ، وشهوة بغير روح .", "وأنا أحس بميل شديد لإنسانة معينة . أعجبني شكلها أعجبني سلوكها وطريقة تصرفها . أعجبتني أخلاقها . أحسست بالارتياح اليها أحسست بهاتف يقول لي هذه التي تكلك. هذه هي ( الشق ) الذي يكمل كيانك وان هذا الميل ليحرك نفسي حركة جادة .. انه ليس تزجية فراغ ولا حلماً في اليقظة . انني أريدها . لا شك عندي في ذلك . لقد رتبت - في خيالي - ان تكون حياتي مع هذه الفتاة . فلأشرع إذن في التنفيذ . فلأخذ الاذن من صاحب الإذن الأول الذي يملك الأمانة . فلأخذ الاذن - في قلبي - من الله . فلأتوجه اليه أن يوفقني اليها وان يتمم شأني على ما يحبه ويرضاه . ثم فلأتوجه"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0083.png"}, {"n": 84, "paras": ["إلى أهلها أطلب يدها وأتفاهم معهم على الأمر . ولأكن في تصرفاتي كما ينبغي حق أقع في نفسها كما وقعت في نفسي ، وأعجبها كما أعجبتني . فلأكن رجلا . فلأكن بحيث تحس انها تستطيع أن تثق بي ، وتطمئن إلي ..", "أو .. أني لا أملك في الوقت الحاضر الوسيلة .. فلأصبر إذن حتى يأذن الله بالتيسير، ولأنصرف إلى العمل الجاد الذي يوصل ، ولأنصرف إلى أهداف الحياة الاخرى التي تتطلب مني الجهود ..", "فاذا تزوجت - الآن أو في المستقبل - هذه الفتاة التي ملت اليها ومالت إلي ، فنحن الآن في حل من المتعة الكاملة التي أباحها الله .. أباحها بلا قيود : ( قد أفلح المؤمنون ، الذين هم في صلاتهم خاشعون ، والذين هم عن اللغو معرضون ، والذين هم للزكاة فاعلون، والذين هم لفروجهم حافظون ، إلا على أزواجهم أو ما ملكت أيمانهم فإنهم غير ملومين) (نساؤكم حرث لكم فأتوا حرثكم أنى شئتم ) ..", "نحن في حل أن نصبح جسداً واحداً وروحاً واحدة. واني لأحس معها بامتزاج كامل لا يعرف أحدنا أين ينتهي وأين يبدأ الآخر . نحن كيان واحد مختلط الاجزاء . وأنا أحس براحة ضميري لانني ألتقي بها على طهارة قلب ونظافة روح . وأنا أستمتع منها بكل ما يستمتع"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0084.png"}, {"n": 85, "paras": ["به جسم من جسم . ولكن لا تمر علينا لحظة جسد خالصة هنالك دائماً ذلك التعاطف القلبي والامتزاج الروحي . وعلاقتي بها تشمل من نفسي دائماً مساحة أكبر من مساحة الحس . حق في لحظة اللقاء الحسي . وأنا بهذا كله أوفر نصيباً من المتعة وأوفر في الاعصاب ..", "هذا أمر الجنس في حساب الاسلام . لا كبت ولا استنكار ولا قذارة بل متاع كامل بكل ما في الفطرة من جوانب المتاع متاع الحس القريب ، مضافاً اليه ألوان من المتعة لا يعرفها الحيوان ويقدرها الانسان ) .", "في القواعد الوقائية :", "والإسلام مع تركيزه الاساسي على إيجاد الحوافز الخيرة في أعماق النفس البشرية .. مع اهتمامه البالغ في توفير الحصانة الذاتية للانسان . الاسلام مع هذا وفوق هذا يضع من الاجراءات الوقائية والاحترازية ما يسد به منافذ الشر على الفرد وعلى المجتمع .", "تجنب المثيرات", "فالاسلام حرم شتى انواع ووسائل الاغراء التي من شأنها إثارة الغرائز وإشاعة الفواحش . كل ذلك في سبيل ان يعيش الانسان في مجتمع نظيف لا أثر للضغوط الخارجية فيه على أعصابه . مجتمع يعين الانسان على سلوك سبيل الفطرة . يعينه ولا يعين عليه ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0085.png"}, {"n": 86, "paras": ["ولذلك كان موقف الإسلام حاسماً وحازماً بالنسبة لكل عامل من عوامل الإفساد في المجتمع . وقاعدته في ذلك ( كل ما يؤدي إلى الحرام فهو حرام ) .. قال الله تعالى ( ان الذين يحبون أن تشيع الفاحشة في الذين آمنوا لهم عذاب أليم في الدنيا والآخرة والله يعلم وأنتم لا تعلمون) وعن ابي هريرة رضي الله عنه قال ( لعن رسول الله ﷺ الرجل يلبس لبس المرأة ، والمرأة تلبس لبس الرجل ) (١) وعن أبي مسعود قال ( لعن الله الواشمات والمستوشمات والمتنمصات (٢) والمتفلجات للحسن المغيرات خلق الله ) . وأخرج مسلم وغيره ( صنفان من أهل النار لم أرهما : قوم معهم سياط كأذناب البقر يضربون بها الناس ، ونساء كاسيات عاريات مائلات مميلات ، رؤوسهن كأسنمة البخت المائلة، لا يدخلن الجنة ولا يعرفن ريحها ، وان ريحها ليوجد من مسيرة كذا وكذا).", "تجنب الاختلاط ومن قبيل قطع دابر الغواية والفتنة بين النساء والرجال حظر الاسلام الاختلاط لغير مقاصد ( العبادة والعلم والجهاد ) وفي حدود الحشمة والحيطة الشرعيتين الواقيتين .", "(١) رواه ابو داود بإسناد صحيح .", "(٢) الأخذ من شعر الحاجب ،"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0086.png"}, {"n": 87, "paras": ["في الحقيقة ان الاختلاط بين الجنسين هو الخطوة الأولى في المسيرة التي تنتهي إلى ما انتهت اليه المجتمعات الغربية من تهتك ومجون .. ولهذا تشدد الاسلام في منع اختلاط النساء بالرجال . علماً بأن هذا الفصل بين الجنسين لم يمنع من قيام حضارة فاقت في عطائها الانساني كل الحضارات، كان للمرأة فيها دور رائد وطليعي. يقول الرسول ﷺ ( ما خلا رجل بامرأة إلا كان الشيطان ثالثهما )(١) ويقول ( إياكم والدخول على النساء فقال رجل من الانصار : افرأيت الحمو ؟ قال الحمو الموت )(٢) . وروى الطبراني أيضاً ( إياكم والخلوة بالنساء والذي نفسي بيده ما خلا رجل بامرأة إلا دخل الشيطان بينهما . ولأن يزحم رجلاً خنزير ملطخ بطين أو حمأة ، خير له من أن يزحم منكبه منكب امرأة لا تحل له ) .", "غض البصر وفي سبيل وقاية الانسان مما يحرك غرائزه ويستثير نوازعه، أمر الاسلام بغض البصر وعدم تتبع العورات . فالنظر محرك الشهوة وباعثها ، والنافذة التي تنفذ من خلالها عوامل الميل والرغبة . فالله تعالى جعل البصر مرآة القلب . فاذا غض العبد بصره غض القلب شهوته. وصدق رسول الله ﷺ", "(١) رواه الترمذي .", "(٢) رواه البخاري ومسلم والترمذي ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0087.png"}, {"n": 88, "paras": ["حيث يقول ( الاثم حواز القلوب وما من نظرة إلا وللشيطان فيها مطمع ) (١) ويقول ( ما من مسلم ينظر إلى محاسن امرأة ثم يغض بصره إلا أحدث الله له عبادة يجد حلاوتها في قلبه ) (٢). ان النظرة كما يقولون فعل السهم في الرمية ، إن لم تقتله جرحته . وهي بمنزلة الشرارة في الحطب ان لم تحرقه كله أحرقت بعضه . قال الرسول ﷺ ( النظرة سهم مسموم من سهام ابليس ، من تركها من مخافتي ابدلته إيماناً يجد حلاوته في قلبه ) (٣) . وفي حديث للرسول ﷺ يقول : ( يا علي لا تتبع النظرة النظرة ، فان لك الأولى وليس لك الآخرة ) . وقديماً قيل : كل الحوادث مبداها من النظر ومعظم النار من مستصغر الشرر كم نظرة فعلت في قلب صاحبها فعل السهام بلا قوس ولا وتر والمرء ما دام ذا عين يقلبها في أعين الغيد موقوف على خطر يسر مقلته ما ضر مهجته لا مرحباً بسرور عاد بالضرر", "(١) رواه البيهقي .", "(٢) رواه أحمد والطبراني .", "(٣) رواه الطبراني والحاكم ."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0088.png"}, {"n": 89, "paras": ["ستر المرأة", "وفي سبيل درء المفاسد عن الفرد والمجتمع أوجب الاسلام على المرأة لباساً يستر جسدها ومفاتنها .. يقول الله تعالى : ( يا أيها النبي قل لأزواجك وبناتك ونساء المؤمنين يدنين عليهن من جلابيبهن . ذلك أدنى أن يعرفن فلا يؤذين ، وكان الله غفوراً رحيماً ) ويروى عن عائشة رضي الله عنها ان أسماء بنت أبي بكر - أختها - دخلت على النبي ﷺ في لباس رقيق بشف عن جسمها . فأعرض النبي ﷺ وقال : ( يا أسماء ان المرأة إذا بلغت الحيض لم يصلح أن يُرى منها إلا هذا وهذا وأشار إلى وجهه وكفيه ) .", "فأين هذا مما عليه نساء اليوم من ملابس فاضحة وأزياء ساقطة تستحي من ارتدائها النساء المؤمنات حتى في مخادعهن ؟", "يقول الاستاذ أبو الأعلى المودودي في كتابه ( الحجاب ) : ان التعبير النفسي الكامل الصحيح الذي قد عبر به الاسلام عن غريزة الحياء الانساني في باب ستر العورات ، لا مثيل له في حضارة من حضارات العالم . ومن حال أرقى الأمم وأعلاها ثقافة اليوم ان رجالها ونساءها لا يتحرجون من كشف أي جزء من أجزاء جسدهم . واللباس عندهم لمجرد الزينة لا للستر . ولكن الاسلام أكثر ما يهمه من اللباس هو الستر دون الزينة . فهو يأمر الرجل والمرأة أن يسترا من جسمها كل الأجزاء التي فيها جاذبية للصنف الآخر . والعري عند الاسلام من الوقاحة وسوء الأدب الذي لا"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0089.png"}, {"n": 90, "paras": ["يكاد حياؤه يصبر عليه بحال من الأحوال . فالاسلام يريد أن يطهر جو المجتمع وبيئته من كل مغريات الفحش والمنكر. وهذه المغريات مصدرها جميعاً الباطن الانساني. فهناك تنشأ جراثيم كل منكر وفاحشة . ومن هناك تبتدىء الحركات الخفيفة التي ربما غفل عنها الانسان الجاهل زاعماً انها هنات لا تضر ولكنها - في رأي الحكيم العليم - علة العار وأصل الأمراض التي تدمر التمدن والأخلاق في المجتمع . ولذلك يريد التعليم الخلقي الاسلامي أن يبعث في باطن الانسان شعوراً نفسياً من الحياء ، يكون من القوة والشدة بحيث يدفعه على محاسبة نفسه بنفسه على الدوام .."], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0090.png"}, {"n": 91, "paras": ["الخلاصة", "ان الاسلام حين يواجه المشكلة الجنسية فانما يواجهها في نطاق مواجهته الشاملة لقضايا ومشكلات الفرد والمجتمع جميعاً . لا ينظر اليها منفصلة أو يتناولها على حدة .", "وهو حين يعالجها فانما يعالجها كعنصر في مركب العلاج الاسلامي الشامل .. العلاج الذي لا يحقق البرء ما لم يكن مستكملا كل عناصره وجزئياته . ما لم يأخذ ككل ويعالج به ككل.. يعالج به فكراً ، ويعالج به نظاماً ، ويعالج به تشريعاً ، ويعالج به عبادة ، ويعالج به اخلاقاً ..", "ان جسم المجتمع كجسم الانسان متداخل التركيب ، تتأثر أعضاؤه بعضها ببعض .. وعافية المجتمع كعافية الانسان لا. تتحقق إلا أن تكون أعضاؤه كلها سليمة ومعافاة ..", "فالمجتمع الذي تحكمه أنظمة وقوانين فاسدة ، ويربى أفراده وفق مناهج فاسدة ، وتقوم وسائل الاعلام فيه على قواعد فاسدة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0091.png"}, {"n": 92, "paras": ["لا يمكن أن تنفع معه جرعة من جرعات العلاج الاسلامي ، بل لا بد له من أخذ العلاج كاملا . انه بحاجة إلى عملية تطبيب تتناول أفكاره ومعتقداته ونظمه وتشريعاته وأخلاقه وعاداته .. ان المشكلة الجنسية كواحدة من كثير من المشاكل التي خلفتها الحضارة الغربية والقوانين الوضعية والفلسفات المادية في أكثر المجتمعات العالمية ، لا يمكن حلها الحل الفطري السليم ما لم تكن القوامة في هذه المجتمعات للاسلام ، في نطاق الحكم ، كما في نطاق التوجيه ، وفي نطاق الاعلام كما في نطاق التعليم سواء بسواء .. ( فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما ) . والله غالب على أمره"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0092.png"}, {"n": 93, "paras": ["جدول المراجع", "المرجع التشريع الجنائي في الاسلام العقوبة في الفقه الاسلامي المرأة بين الفقه والقانون الحجاب منهج التربية الاسلامية تاريخ العلاقات الجنسية الثورة الجنسية حياتنا الجنسية", "النشاط الجنسي جاهلية القرن العشرين الحلال والحرام في الاسلام الأمراض الجنسية حكم الاسلام في النظر الترهيب والترغيب احياء علوم الدين", "المؤلف لعبد القادر عودة لبهنسي لمصطفى السباعي لأبي الأعلى المودودي لمحمد قطب جورج بالوثي هورفت محمد قطب يوسف القرضاوي الدكتور نبيل الطويل الشيخ محمد الحامد الامام المنذري الامام الغزالي"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0093.png"}, {"n": 94, "paras": ["فهرس الموضوعات", "المقدمة التصور عنوان التصرف تصحيح التصور هو الأساس الثورة الجنسية أسبابها ونتائجها الأخلاق والجنس فلسفة الأخلاق في الإسلام النظرية الجنسية في الاسلام الطريق الفطري للاشباع الجنسي الزواج هو الطريق المفهوم السامي للزوجية الاسلام يحض على الزواج العلاقة الجنسية بين الزوجين قدسية العلاقات الزوجية الاسلام والانحرافات الجنسية الاسلام يحذر من الزنا مضار الزنا الصحية مضار الزنا الاجتماعية الاسلام يحذر من اللواط العادة السرية العقوبة في الاسلام وسيلة تربية عن عقوبات الجرائم الجنسية ( ب ) عقوبة الزنا . عقوبة اللواط"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0094.png"}, {"n": 95, "paras": ["٥٨ عقوبة السحاق", "٥٩ عقوبة وطء البهائم", "٦٠ الإباحة الجنسية وأثرها على المجتمعات البشرية", "٦٠ الجنس يبدد الثروة القومية", "٦١ الجنس يقوض الصحة العامة", "٦٢ الجنس يهدم الأواصر المجتمعية", "٦٣ الجنس يخرب الأخلاق الإنسانية", "٦٣ النتيجة", "٦٨ المرأة ووظيفتها في الحياة", "٦٨ المرأة في الحضارة الغربية", "٧٢ المرأة في الحضارة الاسلامية", "٧٥ المنهج الاسلامي لصيانة المجتمع", "٧٦ في القواعد التربوية :", "٧٦ ١ - التربية الروحية", "٧٨ ٢ - التربية الفكرية", "٨٠ ٣ - التربية الجسدية", "٨٦ في القواعد الوقائية", "٨٦ ١ - تجنب المثيرات", "٨٧ ٢ - تجنب الاختلاط", "٨٨ ٣ - غض البصر", "٩٠ ٤ - ستر المرأة ( الحجاب )", "٩٢ الخلاصة"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0095.png"}, {"n": 96, "paras": ["تطلب جميع منشوراتنا من : . الشركة المتحدة للتوزيع بيروت - شارع سورية - بناية محمدي وصالحة ص.ب ٧٤٦٠ هاتف ٢٩٤٤٠١", "الثمن : ٢٥٠ ق. ل.", "مكتبة المنارة الأزهرية طه كمال خضر الأزهري"], "img": "../../../_ocr-work/libocr/yakan-islam-jins/pages/0096.png"}]};
